import { useState, useEffect, useCallback, useMemo, useRef, lazy, Suspense } from 'react'
import { api } from './api'
import { authFetch, wsUrl } from './auth'
import { artifactOf, artifactBody, currentArtifact } from './stageDocs'
import { isNoiseTask } from './noise'
import { STATE_META, STAGE_META } from './constants'
import StageAdvanceDialog from './components/StageAdvanceDialog'
import DecisionInbox from './components/DecisionInbox'
import Rail from './components/Rail'
import MissionBar from './components/MissionBar'
import ListView from './components/ListView'
import PlanView from './components/PlanView'
import TopoView from './components/TopoView'
import GanttView from './components/GanttView'
import EmbedView from './components/EmbedView'
// 想法库依赖 marked/DOMPurify 做 Markdown 渲染，且不是默认视图 → 按需加载
const IdeasView = lazy(() => import('./components/IdeasView'))
import TemplatesView from './components/TemplatesView'
import WorkflowView from './components/WorkflowView'
import StatsView from './components/StatsView'
import ObservabilityView from './components/ObservabilityView'
import MemoryView from './components/MemoryView'
import MioRuntimeView from './components/MioRuntimeView'
import MaterialPanelView from './components/MaterialPanelView'
import SettingsView from './components/SettingsView'
import ScheduledJobsView from './components/ScheduledJobsView'
import CreateModal from './components/CreateModal'
import TaskDetail from './components/TaskDetail'
// DocPanel 依赖 highlight.js（体积大头），只在打开文档时才需要 → 按需加载
const DocPanel = lazy(() => import('./components/DocPanel'))
import ErrorBoundary from './components/ErrorBoundary'
import ErrorBar from './components/ErrorBar'
import ConnectionBanner from './components/ConnectionBanner'
import UpdateBanner from './components/UpdateBanner'

import CommandPalette from './components/CommandPalette'
import ConfirmDialog from './components/ConfirmDialog'
import InputDialog from './components/InputDialog'
import { confirm } from './confirm'
import { applyMotion } from './motion'

// 启动即应用动效偏好（用户关闭动效 / 系统开启「减少动画」时禁用所有动画）
applyMotion()

const VIEW_KEY = 'mio.view'
const CONTRAST_KEY = 'mio.contrast'
const THEME_KEY = 'mio.theme'
const SHOW_NOISE_KEY = 'mio.showNoise'

const ALERT_LABELS = {
  TaskQueueStale: '队列陈旧',
  NoTaskTransition: '状态无跃迁',
  NoConsumers: '无消费者在线',
  SchedulerStateLost: '调度状态丢失',
}

/** 视图级骨架：按需加载的视图（想法库/文档面板）首次打开时的 fallback，避免纯白屏 */
function ViewSkeleton({ label = '正在加载…' }) {
  return (
    <div className="view-skeleton" role="status" aria-busy="true" aria-label={label}>
      <div className="view-skeleton__rows" aria-hidden="true">
        {[0, 1, 2, 3].map(i => <div key={i} className="view-skeleton__row" />)}
      </div>
      <p className="view-skeleton__label">{label}</p>
    </div>
  )
}

// 壳组件：isEmbed 分流必须在 hooks 之前无条件完成，
// AppMain 内的 hooks 数量保持恒定（rules-of-hooks）
export default function App() {
  const isEmbed = typeof window !== 'undefined' && window.location.hash === '#/embed'
  if (isEmbed) {
    return <EmbedView />
  }
  return <AppMain />
}

// eslint-disable-next-line complexity, max-lines-per-function, max-statements
function AppMain() {

  const [allTasks, setAllTasks] = useState([])  // 全量（含已取消/机器噪声），展示时按 showCancelled / showNoise 过滤
  const [showCancelled, setShowCancelled] = useState(false)
  // 机器噪声（创意引擎/洞察消费/自测任务）默认隐藏——E7 实验：1771 个任务里 88% 是这类，
  // 不隐藏则真实决策信息被稀释 9:1。默认值的读取要能容忍 localStorage 不可用。
  const [showNoise, setShowNoise] = useState(() => {
    try { return localStorage.getItem(SHOW_NOISE_KEY) === '1' } catch { return false }
  })
  const [ideas, setIdeas] = useState([])
  const [view, setViewState] = useState(() => {
    try {
      const q = new URLSearchParams(window.location.search).get('view')
      if (q) return q
      const v = localStorage.getItem(VIEW_KEY) || 'workflow'
      // 旧版视图（board/stage/flow）统一合并为 workflow
      return ['board', 'stage', 'flow'].includes(v) ? 'workflow' : v
    } catch { return 'workflow' }
  })
  const [contrast, setContrast] = useState(() => {
    try { return localStorage.getItem(CONTRAST_KEY) === 'high' } catch { return false }
  })
  const [theme, setTheme] = useState(() => {
    try {
      const q = new URLSearchParams(window.location.search).get('theme')
      if (q === 'light' || q === 'dark') return q
      return localStorage.getItem(THEME_KEY) === 'light' ? 'light' : 'dark'
    } catch { return 'dark' }
  })
  const [alerts, setAlerts] = useState([])
  const [ws, setWs] = useState(false)
  const [error, setError] = useState(null)  // { message, type, retry? }
  const [modal, setModal] = useState(false)
  const [detail, setDetail] = useState(null)
  const [docTask, setDocTask] = useState(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [lastSync, setLastSync] = useState(null)
  const [focus, setFocus] = useState(null) // { id, t }
  const [filter, setFilter] = useState({ project: '', workspace: '' })
  const [toasts, setToasts] = useState([])
  const [memoryEvent, setMemoryEvent] = useState(null)  // 最新 memory 事件 (for MemoryView)
  const [wsRetryIn, setWsRetryIn] = useState(null)
  const [cmdOpen, setCmdOpen] = useState(false)  // WS 重连倒计时（秒）
  const [advanceDlg, setAdvanceDlg] = useState(null) // 阶段推进对话框：{ task, next, spec, busy, error }

  const tasks = useMemo(() => {
    let out = allTasks
    if (!showCancelled) out = out.filter(t => t.state !== 'cancelled')
    if (!showNoise) out = out.filter(t => !isNoiseTask(t))
    return out
  }, [allTasks, showCancelled, showNoise])
  const cancelledCount = useMemo(
    () => allTasks.reduce((n, t) => n + (t.state === 'cancelled' ? 1 : 0), 0),
    [allTasks]
  )
  // 被隐藏的噪声条数（不含已取消的重复计数也无妨：这里只用于开关上的提示数字）
  const noiseCount = useMemo(
    () => allTasks.reduce((n, t) => n + (isNoiseTask(t) && t.state !== 'cancelled' ? 1 : 0), 0),
    [allTasks]
  )
  const toggleNoise = useCallback(() => {
    setShowNoise(v => {
      try { localStorage.setItem(SHOW_NOISE_KEY, v ? '0' : '1') } catch { /* ignore */ }
      return !v
    })
  }, [])

  const setView = useCallback((v) => {
    setViewState(v)
    try { localStorage.setItem(VIEW_KEY, v) } catch { /* ignore */ }
  }, [])

  useEffect(() => {
    document.documentElement.dataset.contrast = contrast ? 'high' : 'standard'
    try { localStorage.setItem(CONTRAST_KEY, contrast ? 'high' : 'standard') } catch { /* ignore */ }
  }, [contrast])

  useEffect(() => {
    document.documentElement.dataset.theme = theme
    try { localStorage.setItem(THEME_KEY, theme) } catch { /* ignore */ }
  }, [theme])

  useEffect(() => {
    let alive = true
    const load = () => {
      api.listAlerts()
        .then(d => { if (alive) setAlerts((d && d.alerts) || []) })
        .catch(() => { /* 告警拉取失败不阻塞主界面 */ })
    }
    load()
    const timer = setInterval(load, 30000)
    return () => { alive = false; clearInterval(timer) }
  }, [])

  const toggleContrast = useCallback(() => setContrast(c => !c), [])
  const toggleTheme = useCallback(() => setTheme(t => (t === 'light' ? 'dark' : 'light')), [])

  const loadTasks = useCallback(() => {
    api.listTasks({ cancelled: 'true' })
      .then(data => { setAllTasks(data); setError(null); setLastSync(new Date()) })
      .catch(e => setError({ message: '加载失败: ' + e.message, type: 'api', retry: loadTasks }))
      .finally(() => { setLoading(false); setRefreshing(false) })
  }, [])

  const loadIdeas = useCallback(() => {
    api.listIdeas()
      .then(data => { setIdeas(data?.ideas || []); setError(null) })
      .catch(() => { /* 想法加载失败静默（不影响主看板） */ })
  }, [])

  const refresh = useCallback(() => { setRefreshing(true); loadTasks() }, [loadTasks])

  // sticky：需要用户处理/确认的消息（提交被拦截、任务失败）不自动消失，
  // 必须手动关闭或点击跳转，否则 4 秒后无声消失等于没提示（Phase 2 C-5）。
  const addToast = useCallback((msg, type = 'info', opts = {}) => {
    const id = Date.now() + Math.random()
    const next = { id, msg, type, sticky: !!opts.sticky, taskId: opts.taskId || null }
    setToasts(prev => {
      // R2 C-5 截断策略修正：
      //  · sticky（提交被拦截 / 执行失败）**免驱逐** —— 旧实现 [...prev.slice(-4), next] 对
      //    sticky 一视同仁，2 条 sticky 在场时再来几条普通 toast 就把它们挤掉，
      //    「不自动消失、必须用户处理」的承诺当场失效；
      //  · 同 taskId 的 sticky 去重 —— 同一任务重复失败/重复被拦截只留最新一条。
      //  · 普通 toast 只保留最近 3 条（低价值流水不占屏幕）。
      const kept = prev.filter(t => !(next.sticky && t.sticky && next.taskId && t.taskId === next.taskId))
      const stickies = kept.filter(t => t.sticky)
      const normals = kept.filter(t => !t.sticky).slice(-3)
      return [...stickies, ...normals, next]
    })
    if (!opts.sticky) {
      setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000)
    }
  }, [])

  const dismissToast = useCallback((id) => setToasts(prev => prev.filter(t => t.id !== id)), [])

  useEffect(() => {
    loadTasks()
    loadIdeas()

    let socket = null
    let timer = null
    let retry = 0
    let closed = false
    let nextRetryAt = null  // timestamp when next retry fires
    const setNextRetry = () => {
      if (retry === 0) {
        nextRetryAt = null
        return
      }
      const delay = Math.min(1000 * 2 ** (retry - 1), 15000)
      nextRetryAt = Date.now() + delay * 1000
    }
    const tick = () => {
      if (!nextRetryAt) {
        setWsRetryIn(null)
        return
      }
      const remain = Math.max(0, Math.ceil((nextRetryAt - Date.now()) / 1000))
      setWsRetryIn(remain)
    }
    const tickId = setInterval(tick, 250)
    tick()

    const schedule = () => {
      if (timer) clearTimeout(timer)
      const delay = Math.min(1000 * 2 ** retry, 15000)
      retry += 1
      setNextRetry()
      tick()
      timer = setTimeout(connect, delay)
    }

    const connect = () => {
      if (closed) return
      let s
      try { s = new WebSocket(wsUrl('/ws')) } catch { schedule(); return }
      socket = s
      s.onopen = () => { setWs(true); retry = 0; nextRetryAt = null; setWsRetryIn(null) }
      s.onclose = () => { setWs(false); schedule() }
      s.onerror = () => { try { s.close() } catch { /* ignore */ } }
      // eslint-disable-next-line complexity
      s.onmessage = (e) => {
        try {
          const data = JSON.parse(e.data)
          if (data.type === 'task_update' && data.event) {
            const ev = data.event
            const p = ev.payload || {}
            // 全部走 titleOf：以前 stage_advanced/cancelled/completed 显示 entity_id 裸哈希，
            // 而 failed/rejected 显示标题 —— 同类事件两种显示规则（R2 C-5）
            if (ev.type === 'task.stage_advanced') addToast(`「${titleOf(ev.entity_id)}」 ${p.from||'?'} → ${p.to||'?'}`, 'info')
            else if (ev.type === 'task.cancelled') addToast(`「${titleOf(ev.entity_id)}」 已取消`, 'warn')
            else if (ev.type === 'task.completed') addToast(`「${titleOf(ev.entity_id)}」 已完成`, 'ok')
            else if (ev.type === 'task.failed') {
              addToast(`「${titleOf(ev.entity_id)}」 执行失败`, 'danger', { sticky: true, taskId: ev.entity_id })
            }
            // 窄门禁（d468e633 FR-5）：提交被拦截 —— 打断式红色通知。
            // 后端发 entity="task"（events.py 的 MESSAGE_TYPES 不含 run），
            // 所以走 task_update 通道才能收到。
            else if (ev.type === 'run.result_rejected') {
              addToast(`「${titleOf(ev.entity_id)}」 提交被拦截：${p.message || '零改动'}`, 'danger', { sticky: true, taskId: ev.entity_id })
            }
          } else if (data.type === 'idea_update' && data.event) {
            addToast(`想法更新: ${data.event.entity_id}`, 'info')
          } else if (data.type === 'memory_update' && data.event) {
            // 实时把 memory 事件传给 MemoryView（独立 state 避免全量重渲染）
            setMemoryEvent(data)
          } else if (data.type === 'update_status') {
            setLastSync(new Date())   // 触发 UpdateBanner 立即刷新
            if (data.kind === 'update_available' && data.status && data.status.latest) {
              addToast(`发现新版本 v${data.status.latest}`, 'ok')
            }
          }
        } catch { /* ignore parse errors */ }
      }
    }

    connect()
    // 轮询频率分层（任务 613bc0ca · FR-5）：
    //  · 任务列表 5s —— 主视图，WS 事件之外仍需兜底刷新，手感不能牺牲；
    //  · 想法列表 30s —— 非主视图，5s 拉一次只是白白烧服务端（实测 /ideas 17ms ×
    //    多标签页叠加可观）；hub 已有 WS 推送负责实时性。
    const interval = setInterval(() => { loadTasks() }, 5000)
    const ideasInterval = setInterval(() => { loadIdeas() }, 30000)
    return () => {
      closed = true
      if (timer) clearTimeout(timer)
      clearInterval(interval)
      clearInterval(ideasInterval)
      clearInterval(tickId)
      if (socket) socket.close()
    }
  }, [loadTasks, loadIdeas])

  const createTask = async (payload) => {
    try {
      await api.createTask(payload)
      setModal(false)
      loadTasks()
    } catch (e) {
      setError('创建失败: ' + e.message)
      throw e   // 抛出让 CreateModal 在浮层内部显示，不再「点了没反应」
    }
  }

  /**
   * 取消任务（R2 C-1）：三个入口（看板 ×、详情、列表行内）共用，**唯一**确认点在这里。
   * 之前看板/详情零确认直接执行、列表页另有一套自建弹窗且显示裸 ID，
   * 三处文案与焦点策略不一致。现在统一走 promise 式 confirm()（已接 overlayStack，
   * 自动成为栈顶，Esc 只关它，默认焦点在「取消」键上）。
   * 返回值：true = 已取消，false = 用户放弃 / 失败 —— 调用方据此决定是否关面板。
   */
  const cancelTask = async (id) => {
    const t = allTasks.find(x => x.id === id)
    const ok = await confirm(
      `取消任务「${t?.title || id}」？任务将不再被 agent 领取，可在「已取消」中查看。`,
      { title: '取消任务', danger: true, okText: '取消任务' }
    )
    if (!ok) return false
    try {
      await api.advanceStage(id, { target_stage: 'cancelled' })
      loadTasks()
      // 取消后任务默认从列表消失（showCancelled 关着），必须给一条确认，否则像是点了个寂寞
      addToast(`「${t?.title || id}」 已取消，可在「已取消」中查看`, 'ok')
      return true
    } catch (e) {
      setError('取消失败: ' + e.message)
      return false
    }
  }

  const retryTask = async (id) => {
    try {
      await api.retryTask(id)
      loadTasks()
      // 重试后**不关详情**（用户 2026-11-04）：任务从 failed 变成 queued/ready，
      // 详情里的「重试」按钮要消失、「推进阶段」要从 ready 起算——不刷新快照的话
      // 面板还停在 failed 的旧数据上，接着操作全是错的。
      const fresh = await api.getTask(id)
      setDetail(prev => (prev && prev.id === id ? fresh : prev))
      addToast(`「${fresh.title || id}」 已重新排队，阶段重置为 ${fresh.stage}`, 'ok')
      return true
    } catch (e) {
      setError('重试失败: ' + e.message)
      throw e
    }
  }

  // 返回 { ok, message }：让调用方（如阶段推进对话框）能把错误显示在浮层内部，
  // 而不是只落到 App 层 ErrorBar（会被浮层遮罩盖住，用户看到「点了没反应」）。
  const advanceStage = async (id, body) => {
    try {
      await api.advanceStage(id, body)
      loadTasks()
      return { ok: true }
    } catch (e) {
      const message = '推进阶段失败: ' + (e.message || '阶段不合法')
      setError(message)
      return { ok: false, message }
    }
  }

  const _moveToStage = async (id, body) => {
    try { await api.moveToStage(id, body); loadTasks() }
    catch (e) { setError('移动阶段失败: ' + (e.message || '阶段不合法')) }
  }

  // 阶段推进对话框：替代 window.prompt（Phase 2 C-4）
  // toast 里显示任务标题而非裸 ID；WS 回调是长生命周期闭包，用 ref 取最新列表
  const tasksRef = useRef([])
  useEffect(() => { tasksRef.current = allTasks }, [allTasks])
  const titleOf = useCallback((id) => tasksRef.current.find(t => t.id === id)?.title || id, [])

  const confirmAdvance = useCallback(async (val, mode) => {
    const d = advanceDlg
    if (!d) return
    setAdvanceDlg(prev => prev ? { ...prev, busy: true, error: '' } : null)
    const body = { target_stage: d.next }
    Object.assign(body, artifactBody(d.next, val, mode))
    const r = await advanceStage(d.task.id, body)
    if (r && r.ok === false) {
      // 失败不外抛到 App 层 ErrorBar（会被浮层遮罩盖住），显示在对话框内部
      setAdvanceDlg(prev => prev ? { ...prev, busy: false, error: r.message } : null)
      return
    }
    setAdvanceDlg(null)
    addToast(`「${d.task.title}」 已推进到 ${STAGE_META[d.next]?.label || d.next}`, 'ok')
  }, [advanceDlg, advanceStage, addToast])

  /**
   * 阶段推进的唯一入口（R2 C-4 归一）：看板「推进」按钮、依赖图卡片按钮、
   * 依赖图拖拽落点、详情面板全部走这里，产出物统一由 StageAdvanceDialog 收集。
   * @param task        目标任务
   * @param targetStage 可选：显式目标阶段（依赖图拖到任意列 / 回溯时用）；
   *                    不传则按「下一阶段」推进（正向流程的唯一自然语义）。
   */
  const advanceTaskStage = async (task, targetStage) => {
    const next = targetStage || { brainstorming:'design', design:'planning', planning:'ready',
                   ready:'implementing', implementing:'review', review:'done' }[task.stage]
    if (!next || next === task.stage) return
    // 产出物要求查表（stageDocs.js，与后端一致）；无要求的阶段直接推进，不再弹空输入框
    const spec = artifactOf(next)
    if (!spec) {
      // 以前这条分支静默返回：点了/拖了没有任何反馈，用户无法判断是否成功（R2 C-4 补 toast）
      const r = await advanceStage(task.id, { target_stage: next })
      if (r && r.ok) addToast(`「${task.title}」 已推进到 ${STAGE_META[next]?.label || next}`, 'ok')
      return
    }
    setAdvanceDlg({ task, next, spec: { ...spec, initial: currentArtifact(task, next) }, busy: false, error: '' })
  }

  /**
   * 状态（state）**不可**由前端直接修改——这是被证实的后端约束，不是遗漏：
   *  · PATCH /tasks/{id} 的可编辑字段白名单里没有 state（mio_taskhub/api/tasks.py:381-390
   *    的 editable 列表只有 title/priority/project/doc_paths… 等业务字段）；
   *  · task.state 的唯一写入口是 state machine 的 apply_transition（mio_taskhub/workflow/
   *    transitions.py:62），调用方分别是 agent 领取（claim.py）、run 上报（api/runs.py:137）、
   *    阶段推进/取消/重试（api/task_stages.py:326/410/447）与后台调度（background.py:41）。
   * 也就是说：queued→claimed→running→completed 由 **agent 领取与执行** 驱动，
   * 没有「人手动置 state」的接口。
   *
   * 因此这里**绝不**做乐观的本地 state 写入：旧实现只 setAllTasks 不调 API，卡片会在
   * 5 秒轮询后无声弹回原泳道，用户误以为拖拽成功（Phase 2 A1 / C-1 「假成功」）。
   * 正确做法是承认约束 —— 看板「按状态」视图已禁止跨列拖拽（见 BoardView canDrag），
   * 本函数退化为兜底：只解释原因，不改数据。
   */
  const moveTask = useCallback((taskId, newState) => {
    const t = allTasks.find(x => x.id === taskId)
    const label = STATE_META[newState]?.label || newState
    addToast(`「${t?.title || taskId}」的状态由 agent 领取/执行驱动，无法手动改到「${label}」`, 'warn')
  }, [allTasks, addToast])


  const moveTaskStage = useCallback(async (taskId, newStage) => {
    setAllTasks(prev => prev.map(t => t.id === taskId ? { ...t, stage: newStage } : t))
    setDetail(prev => prev && prev.id === taskId ? { ...prev, stage: newStage } : prev)
    try {
      await api.moveToStage(taskId, { target_stage: newStage })
      loadTasks()
    } catch (e) {
      setError('移动阶段失败: ' + (e.message || '阶段不合法'))
      loadTasks()
    }
  }, [loadTasks])

  const closeDetail = useCallback(() => setDetail(null), [])

  const openTask = useCallback(async (t) => {
    try {
      setDetail(await api.getTask(t.id))
      setError(null)
    } catch (e) {
      setDetail(null)
      setError('加载详情失败: ' + e.message)
    }
  }, [])

  // 键盘快捷键（必须在 openTask 定义之后）
  useEffect(() => {
      const VIEW_IDS = ['workflow', 'list', 'plan', 'topo', 'gantt', 'ideas', 'templates', 'scheduled', 'stats', 'memory']
    // eslint-disable-next-line complexity
    const handler = (e) => {
      // 排雷（Phase 2 F2 / R2 C-2）：中文输入法组词中不响应任何单键快捷键 ——
      // 拼音候选词面板打开时按 1-9 是选字、按 n 是输入，不是切视图/新建。
      // keyCode 229 是 Safari/旧浏览器组词态的兜底信号（此时 key 常为 'Process'）。
      if (e.isComposing || e.keyCode === 229) return
      // 富文本场景（contenteditable）里打字同样不该触发全局快捷键。
      const tgt = e.target
      if (tgt?.isContentEditable || tgt?.closest?.('[contenteditable="true"]')) return

      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault()
        setCmdOpen(v => !v)
        return
      }
      if (!e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey) {
        const num = parseInt(e.key)
        if (num >= 1 && num <= 9) {
          const tag = e.target.tagName
          if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return
          e.preventDefault()
          setView(VIEW_IDS[num - 1])
          return
        }
        if (e.key === 'n' || e.key === 'N') {
          const tag = e.target.tagName
          if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return
          e.preventDefault()
          setModal(true)
          return
        }
        if (e.key === '/') {
          const tag = e.target.tagName
          if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return
          e.preventDefault()
          setCmdOpen(true)
          return
        }
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [setView])

  const handleCmdNavigate = useCallback((viewId, taskId) => {
    setView(viewId)
    if (taskId) openTask({ id: taskId })
  }, [setView, openTask])

  const refreshDetail = useCallback(async () => {
    if (detail) {
      try { setDetail(await api.getTask(detail.id)) } catch { /* 静默刷新失败 */ }
    }
  }, [detail])

  const toggleSubtask = useCallback(async (sid, done) => {
    if (!detail) return
    try {
      await api.updateSubtask(detail.id, sid, { status: done ? 'done' : 'pending' })
      await refreshDetail()
    } catch (e) {
      setError('更新子任务失败: ' + e.message)
    }
  }, [detail, refreshDetail])

  const _focusLane = useCallback((id) => {
    setView('workflow')
    setFocus({ id, t: Date.now() })
  }, [setView])

  const projectOptions = [...new Set([
    ...tasks.map(t => t.project).filter(Boolean),
    ...ideas.map(i => i.project).filter(Boolean),
  ])].sort()
  const workspaceOptions = [...new Set(tasks.map(t => t.workspace).filter(Boolean))].sort()

  const filteredTasks = filter.project
    ? tasks.filter(t => t.project === filter.project)
    : filter.workspace
      ? tasks.filter(t => t.workspace === filter.workspace)
      : tasks
  const filteredIdeas = filter.project
    ? ideas.filter(i => i.project === filter.project)
    : ideas

  const activeAlerts = alerts.filter(a => a.active)
  const alertNames = [...new Set(activeAlerts.map(a => ALERT_LABELS[a.name] || a.name))]
  const hasCritical = activeAlerts.some(a => a.severity === 'critical')

  return (
    <div className="shell">
      <div className="ambient" aria-hidden="true" />
      <Rail view={view} onChange={setView} wsLive={ws} contrast={contrast} onToggleContrast={toggleContrast} theme={theme} onToggleTheme={toggleTheme} />

      <div className="main">
        <MissionBar
          tasks={filteredTasks}
          ws={ws}
          lastSync={lastSync}
          refreshing={refreshing}
          onRefresh={refresh}
          onOpenModal={() => setModal(true)}
          filter={filter}
          onFilterChange={setFilter}
          projectOptions={projectOptions}
          workspaceOptions={workspaceOptions}
          showCancelled={showCancelled}
          cancelledCount={cancelledCount}
          onToggleCancelled={() => setShowCancelled(s => !s)}
          showNoise={showNoise}
          noiseCount={noiseCount}
          onToggleNoise={toggleNoise}
        />

        {activeAlerts.length > 0 && (
          <div className={`alert-strip alert-strip--${hasCritical ? 'critical' : 'warning'}`} role="alert">
            <span className="alert-strip__dot" aria-hidden="true" />
            <strong className="alert-strip__title">{hasCritical ? '系统异常' : '系统警告'}</strong>
            <span className="alert-strip__msg">
              {activeAlerts.length} 条活跃告警：{alertNames.join(' · ')}
            </span>
            <button className="alert-strip__btn" onClick={() => setView('observability')}>
              查看观测台 →
            </button>
          </div>
        )}

        {/* 决策面板（E7 产品化）：待决策 / 待验收 / 失败待处置——只做入口，点行开详情 */}
        <DecisionInbox allTasks={allTasks} onOpenTask={openTask} />

        <ConnectionBanner wsLive={ws} lastSync={lastSync} retryIn={wsRetryIn} />
        <UpdateBanner eventTick={lastSync} onOpenSettings={() => setView('settings')} />

        {error && (
          <ErrorBar
            message={typeof error === 'string' ? error : error.message}
            errorType={typeof error === 'object' ? (error.type || 'unknown') : 'unknown'}
            onRetry={typeof error === 'object' && error.retry ? () => { error.retry(); setError(null) } : null}
            onDismiss={() => setError(null)}
          />
        )}

        {toasts.length > 0 && (
          // sticky 型（提交被拦截 / 执行失败）用 role=alert，不自动消失
          <div className="toast-container" aria-live="polite">
            {toasts.map(t => (
              <div key={t.id}
                   className={`toast toast--${t.type}${t.sticky ? ' toast--sticky' : ''}`}
                   role={t.sticky ? 'alert' : undefined}>
                <span className="toast__msg">{t.msg}</span>
                {t.sticky && (
                  <>
                    <button className="toast__link" onClick={() => { if (t.taskId) openTask({ id: t.taskId }); dismissToast(t.id) }}>
                      查看
                    </button>
                    <button className="toast__x" onClick={() => dismissToast(t.id)} aria-label="关闭提示">×</button>
                  </>
                )}
              </div>
            ))}
          </div>
        )}

        <main className="viewport">
          <div className="view-fade" key={view}>
            <ErrorBoundary onError={(e) => {
              console.error('[App ErrorBoundary]', e);
              try {
                authFetch('/api/v1/memory/observer/ingest', {
                  method: 'POST', headers: {'Content-Type': 'application/json'},
                  body: JSON.stringify({
                    trace_id: 'web-ui-' + Date.now(),
                    event_type: 'react_render_error',
                    payload: { name: e?.name, message: e?.message?.slice(0, 200) },
                    outcome: 'failure',
                  }),
                }).catch(() => { /* 后台刷新失败不打断交互 */ });
              } catch { /* 上报失败静默 */ }
            }}>
            {view === 'workflow' && (
              <WorkflowView
                tasks={filteredTasks}
                onMoveState={moveTask}
                onMoveStage={moveTaskStage}
                onCancel={cancelTask}
                onOpen={openTask}
                onAdvanceTask={advanceTaskStage}
                loading={loading}
                focus={focus}
              />
            )}
            {view === 'list' && (
              <ListView
                tasks={filteredTasks}
                onCancel={cancelTask}
                onOpen={openTask}
                onOpenModal={() => setModal(true)}
                loading={loading}
              />
            )}
            {view === 'plan' && (
              <PlanView tasks={filteredTasks} />
            )}
            {view === 'topo' && (
              <TopoView tasks={filteredTasks} onOpen={openTask} />
            )}
            {view === 'gantt' && (
              <GanttView tasks={filteredTasks} onOpen={openTask} />
            )}
            {view === 'ideas' && (
              <Suspense fallback={<ViewSkeleton label="正在加载想法库…" />}>
                <IdeasView ideas={filteredIdeas} onReload={loadIdeas}
                           onOpenTask={(id) => { setView('workflow'); openTask({ id }) }} />
              </Suspense>
            )}
            {view === 'templates' && (
              <TemplatesView />
            )}
            {view === 'scheduled' && (
              <ScheduledJobsView onNavigateToTask={(id) => { setView('workflow'); openTask({ id }) }} />
            )}
            {view === 'stats' && (
              <StatsView />
            )}
            {view === 'memory' && (
              <MemoryView liveEvent={memoryEvent} />
            )}
            {view === 'mio' && (
              <MioRuntimeView />
            )}
            {view === 'material' && (
              <MaterialPanelView />
            )}
            {view === 'settings' && (
              <SettingsView />
            )}
            {view === 'observability' && (
              <ObservabilityView onOpenTask={(id) => openTask({ id })} />
            )}
            </ErrorBoundary>
          </div>
        </main>
      </div>

      {modal && <CreateModal onClose={() => setModal(false)} onCreate={createTask} />}
      {advanceDlg && (
        <StageAdvanceDialog
          task={advanceDlg.task}
          nextStage={advanceDlg.next}
          spec={advanceDlg.spec}
          busy={advanceDlg.busy}
          error={advanceDlg.error}
          onCancel={() => setAdvanceDlg(null)}
          onConfirm={confirmAdvance}
        />
      )}
      {/* 详情与推进弹窗同为 .overlay（z-index:100），且详情在 DOM 里后渲染，
          于是推进弹窗被整层压住（用户实测「盖住弹窗」）。从详情发起推进时先收起详情：
          弹窗独占焦点，任务标题与目标阶段在弹窗里都有，背后那张详情没有信息增量。 */}
      {detail && (
        <TaskDetail
          task={detail}
          tasks={tasks}
          onClose={closeDetail}
          onCancel={cancelTask}
          onMove={moveTask}
          onToggleSubtask={toggleSubtask}
          onAdvance={(t, s) => { closeDetail(); advanceTaskStage(t, s) }}
          onOpenDocs={() => setDocTask(detail)}
          onOpenTask={openTask}
          onRetry={retryTask}
        />
      )}
      {docTask && (
        // 懒加载首次打开时 chunk 还在路上：给即时占位，否则 fallback={null} 让画面毫无反应
        // （本地 dev 快，生产冷加载可感知数秒）。复用 docpanel 背板样式，视觉上等同面板已开（R2 C-6）。
        <Suspense fallback={
          <div className="docpanel docpanel--loading" role="status" aria-busy="true" aria-label="正在加载文档面板">
            <span className="docpanel__loading-text">正在加载文档…</span>
          </div>
        }>
          <DocPanel task={docTask} onClose={() => setDocTask(null)} />
        </Suspense>
      )}
      <CommandPalette
        open={cmdOpen}
        onClose={() => setCmdOpen(false)}
        onNavigate={handleCmdNavigate}
        tasks={tasks}
      />
      <ConfirmDialog />
      <InputDialog />
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import { LANES, STAGES, fmtDur, parseUtc, isFrozenReviewNoise } from '../constants'
import TaskCard from './TaskCard'

const SCENES = [
  { id: 'today', label: '今日聚焦' },
  { id: 'overdue', label: '逾期' },
  { id: 'all', label: '全部' },
]

function isToday(iso) {
  if (!iso) return false
  const d = parseUtc(iso)
  if (!d || Number.isNaN(+d)) return false
  const n = new Date()
  return d.getFullYear() === n.getFullYear() && d.getMonth() === n.getMonth() && d.getDate() === n.getDate()
}

function isOverdue(t) {
  if (!t.due_at) return false
  if (t.state === 'completed' || t.state === 'cancelled') return false
  const d = parseUtc(t.due_at)
  return d && !Number.isNaN(+d) && d < new Date()
}

const SORTERS = {
  created: (a, b) => String(b.created_at || '').localeCompare(String(a.created_at || ''))
    || (b.priority ?? 0) - (a.priority ?? 0),
  priority: (a, b) => (b.priority ?? 0) - (a.priority ?? 0)
    || String(b.created_at || '').localeCompare(String(a.created_at || '')),
}

// eslint-disable-next-line complexity
export default function BoardView({ tasks, onMove, onCancel, onOpen, loading, focus, groupBy = 'state' }) {
  const [dragging, setDragging] = useState(null)
  const [overPos, setOverPos] = useState(null)
  const [flashId, setFlashId] = useState(null)
  const [scene, setScene] = useState('all')
  const [sort, setSort] = useState('created')
  const laneRefs = useRef({})

  const lanes = groupBy === 'stage' ? STAGES : LANES
  const groupField = groupBy === 'stage' ? 'stage' : 'state'
  // 拖拽只在「按阶段」视图可用：阶段有 POST /tasks/{id}/stage/move 支撑。
  // 状态（state）由 agent 领取/执行驱动，后端没有置 state 的接口（见 App.moveTask 注释），
  // 所以「按状态」视图必须禁止跨列拖拽——否则就是一次假成功（Phase 2 C-1）。
  const canDrag = groupBy === 'stage'

  useEffect(() => {
    if (!focus) return
    setFlashId(focus.id)
    const el = laneRefs.current[focus.id]
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' })
    const t = setTimeout(() => setFlashId(null), 1400)
    return () => clearTimeout(t)
  }, [focus])

  const isWorkstreamMember = t =>
    (t.labels || []).some(l => String(l).startsWith('part-of:'))
  const baseTasks = tasks.filter(t => !isWorkstreamMember(t))
  const hiddenMembers = tasks.length - baseTasks.length

  const filtered = scene === 'all' ? baseTasks
    : scene === 'today' ? baseTasks.filter(t => isToday(t.due_at) || t.stage === 'ready' || t.stage === 'implementing')
    : baseTasks.filter(isOverdue)

  // 统计口径：排除已冻结的 idea 评审风暴历史噪声（数据仍在，列表可查）。
  const noise = filtered.filter(isFrozenReviewNoise)
  const visible = noise.length ? filtered.filter(t => !isFrozenReviewNoise(t)) : filtered

  const byLane = Object.fromEntries(lanes.map(l => [
    l.id,
    [...visible.filter(t => (t[groupField] || '') === l.id)].sort(SORTERS[sort]),
  ]))

  const laneTotal = (id) => byLane[id].reduce((s, t) => s + (t.est_duration_min || 0), 0)
  const totalTasks = visible.length
  const totalDur = visible.reduce((s, t) => s + (t.est_duration_min || 0), 0)
  const noiseDur = noise.reduce((s, t) => s + (t.est_duration_min || 0), 0)
  const doneLane = groupBy === 'stage' ? 'done' : 'completed'
  const doneCount = (byLane[doneLane] || []).length
  const progress = totalTasks ? Math.round((doneCount / totalTasks) * 100) : 0

  const sceneCounts = {
    today: baseTasks.filter(t => !isFrozenReviewNoise(t)).filter(t => isToday(t.due_at) || t.stage === 'ready' || t.stage === 'implementing').length,
    overdue: baseTasks.filter(t => !isFrozenReviewNoise(t)).filter(isOverdue).length,
    all: baseTasks.length - baseTasks.filter(isFrozenReviewNoise).length,
  }

  const clearDrag = () => { setDragging(null); setOverPos(null) }

  const handleDrop = (laneId) => {
    if (!canDrag) { clearDrag(); return }
    if (dragging && dragging !== laneId) onMove(dragging, laneId)
    clearDrag()
  }

  const handleOver = (e, laneId) => {
    if (!canDrag) return
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
    const cards = e.currentTarget.querySelectorAll('.task')
    let index = cards.length
    for (let i = 0; i < cards.length; i++) {
      const r = cards[i].getBoundingClientRect()
      if (e.clientY < r.top + r.height / 2) { index = i; break }
    }
    setOverPos({ lane: laneId, index })
  }

  return (
    <div className="board-wrap">
      <div className="board-stats" role="status" aria-label="看板统计">
        <span className="board-stats__total">{totalTasks} 任务</span>
        <span className="board-stats__dur">· {fmtDur(totalDur)}</span>
        <span className="board-stats__progress">完成 {doneCount}/{totalTasks} ({progress}%)</span>
        {noise.length > 0 && (
          <span className="board-stats__noise"
                title="idea 评审子系统 2026-10-19 的重建风暴（已冻结），从统计口径排除；数据仍可在列表/详情查看">
            已排除历史噪声 {noise.length} 条 · {fmtDur(noiseDur)}
          </span>
        )}
        {hiddenMembers > 0 && (
          <span className="board-stats__noise"
                title="带 part-of 标签的工作流成员只在任务详情的“工作流”面板展示；看板只显示主任务">
            已隐藏工作流成员 {hiddenMembers} 个
          </span>
        )}
        {!canDrag && (
          <span className="board-stats__hint"
                title="任务状态由 agent 领取/执行驱动，前端没有置 state 的接口；需要调整请切到「按阶段」拖拽，或在详情里「推进阶段」">
            状态列由 agent 领取驱动 · 拖拽改状态不可用（切「按阶段」可拖）
          </span>
        )}
        <span className="board-stats__bar" aria-hidden="true">
          <span className="board-stats__fill" style={{ width: `${progress}%` }} />
        </span>
      </div>

      <div className="board-scenes">
        {SCENES.map(s => (
          <button
            key={s.id}
            className={`board-scene${scene === s.id ? ' is-on' : ''}`}
            onClick={() => setScene(s.id)}
          >
            {s.label}
            <span className="board-scene__count">{sceneCounts[s.id]}</span>
          </button>
        ))}
      </div>

      <label className="board-sort">
        <span>排序</span>
        <select className="toolbar__select" value={sort}
                onChange={e => setSort(e.target.value)} aria-label="看板排序">
          <option value="created">创建时间（新→旧）</option>
          <option value="priority">优先级</option>
        </select>
      </label>

      <div className="pipeline">
        // eslint-disable-next-line complexity
        {lanes.map(lane => {
          const items = byLane[lane.id]
          const total = laneTotal(lane.id)
          const slot = dragging && overPos && overPos.lane === lane.id ? overPos.index : null

          const body = []
          items.forEach((t, i) => {
            if (slot === i) body.push(<div key="__slot" className="drop-slot">松开以放置</div>)
            body.push(
              <TaskCard
                key={t.id}
                task={t}
                index={i}
                onCancel={onCancel}
                onDragStart={setDragging}
                onOpen={onOpen}
                onMove={onMove}
                canDrag={canDrag}
              />
            )
          })
          if (dragging && slot !== null && slot >= items.length) {
            body.push(<div key="__slot" className="drop-slot">松开以放置</div>)
          }

          return (
            <section
              key={lane.id}
              ref={el => { laneRefs.current[lane.id] = el }}
              className={`lane${lane.tone === 'live' ? ' is-live' : ''}${overPos && overPos.lane === lane.id ? ' is-over' : ''}${flashId === lane.id ? ' is-flash' : ''}`}
              onDragOver={e => handleOver(e, lane.id)}
              onDragLeave={() => setOverPos(v => v && v.lane === lane.id ? null : v)}
              onDrop={e => { e.preventDefault(); handleDrop(lane.id) }}
              aria-label={`${lane.label}列`}
            >
              <header className="lane__head">
                <span className={`lane__dot${lane.tone ? ` is-${lane.tone}` : ''}`} />
                <span className="lane__title">{lane.en}</span>
                <span className="lane__count" aria-live="polite">{items.length}</span>
                {total > 0 && <span className="lane__sum">· {fmtDur(total)}</span>}
              </header>

              <div className="lane__body">
                {loading && items.length === 0 && (
                  <>
                    <div className="skeleton" style={{ '--i': 0 }} />
                    <div className="skeleton" style={{ '--i': 1 }} />
                  </>
                )}

                {!loading && body}

                {!loading && items.length === 0 && !dragging && (
                  <div className="lane__empty">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
                      <rect x="3" y="4" width="18" height="16" rx="3" />
                      <path d="M12 8v8M8 12h8" />
                    </svg>
                    <span>暂无{lane.label}任务</span>
                  </div>
                )}
              </div>

              {lane.id !== 'failed' && lane.id !== 'cancelled' && (
                <div className="lane__flow" aria-hidden="true">
                  <svg width="26" height="10" viewBox="0 0 26 10" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
                    <path d="M1 5h22M19 1l4 4-4 4" />
                  </svg>
                </div>
              )}
            </section>
          )
        })}
      </div>
    </div>
  )
}

import { useEffect, useState, useCallback, useRef, useMemo } from 'react'
import { useOverlayStack } from '../lib/overlayStack'

const VIEWS = [
  { id: 'workflow', label: '工作流', icon: '⬡' },
  { id: 'list', label: '列表', icon: '☰' },
  { id: 'plan', label: '空闲计划', icon: '🌙' },
  { id: 'topo', label: '拓扑', icon: '◎' },
  { id: 'gantt', label: '甘特', icon: '▬' },
  { id: 'ideas', label: '想法', icon: '💡' },
  { id: 'templates', label: '模板', icon: '📋' },
  { id: 'scheduled', label: '定时任务', icon: '⏱' },
  { id: 'stats', label: '统计', icon: '📊' },
  { id: 'memory', label: '记忆', icon: '🧠' },
  // 以下是 2026-10-28 从导航栏下线、但命令面板仍可进入的视图
  { id: 'observability', label: '观测台', icon: '📈' },
  { id: 'mio', label: 'Mio 运行时', icon: '🔌' },
  { id: 'material', label: '素材面板', icon: '🗂' },
]

export default function CommandPalette({ open, onClose, onNavigate, tasks = [] }) {
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState(0)
  const inputRef = useRef(null)
  const listRef = useRef(null)

  // Esc 交给浮层栈（只由栈顶响应）；输入框内不再单独处理 Esc
  useOverlayStack(onClose, open)

  useEffect(() => {
    if (open) {
      setQuery('')
      setSelected(0)
      setTimeout(() => inputRef.current?.focus(), 50)
    }
  }, [open])

  const results = useMemo(() => {
    const q = query.toLowerCase().trim()
    const items = []

    // Navigation items
    const views = q
      ? VIEWS.filter(v => v.label.toLowerCase().includes(q) || v.id.includes(q))
      : VIEWS
    for (const v of views) {
      items.push({ type: 'view', id: v.id, label: v.label, icon: v.icon })
    }

    // Task search
    if (q && tasks.length > 0) {
      const matched = tasks.filter(t =>
        t.title.toLowerCase().includes(q) ||
        t.id.toLowerCase().includes(q) ||
        (t.project || '').toLowerCase().includes(q)
      ).slice(0, 8)
      for (const t of matched) {
        items.push({
          type: 'task',
          id: t.id,
          label: t.title,
          stage: t.stage,
          state: t.state,
          project: t.project,
        })
      }
    }

    return items
  }, [query, tasks])

  useEffect(() => { setSelected(0) }, [query])

  const execute = useCallback((item) => {
    if (!item) return
    if (item.type === 'view') {
      onNavigate(item.id)
    } else if (item.type === 'task') {
      onNavigate('workflow', item.id)
    }
    onClose()
  }, [onNavigate, onClose])

  const handleKeyDown = useCallback((e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelected(s => Math.min(s + 1, results.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelected(s => Math.max(s - 1, 0))
    } else if (e.key === 'Enter') {
      e.preventDefault()
      execute(results[selected])
    }
  }, [results, selected, execute, onClose])

  // Scroll selected into view
  useEffect(() => {
    const el = listRef.current?.children[selected]
    el?.scrollIntoView({ block: 'nearest' })
  }, [selected])

  if (!open) return null

  return (
    <div className="cmd-overlay" onClick={onClose}>
      <div className="cmd-palette" onClick={e => e.stopPropagation()} role="dialog" aria-label="命令面板">
        <div className="cmd-input-wrap">
          <span className="cmd-input-icon">⌘</span>
          <input
            ref={inputRef}
            className="cmd-input"
            placeholder="搜索视图、任务…"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            role="combobox"
            aria-label="搜索视图或任务"
            aria-autocomplete="list"
            aria-expanded={results.length > 0}
            aria-controls="cmd-listbox"
            aria-activedescendant={results[selected] ? `cmd-opt-${results[selected].type}-${results[selected].id}` : undefined}
          />
          <kbd className="cmd-esc">ESC</kbd>
        </div>
        <div className="cmd-list" ref={listRef} id="cmd-listbox" role="listbox" aria-label="命令与任务结果">
          {results.length === 0 ? (
            <div className="cmd-empty" role="status">无匹配结果</div>
          ) : (
            results.map((item, i) => (
              <div
                key={`${item.type}-${item.id}`}
                id={`cmd-opt-${item.type}-${item.id}`}
                role="option"
                aria-selected={i === selected}
                className={`cmd-item${i === selected ? ' is-selected' : ''}`}
                onClick={() => execute(item)}
                onMouseEnter={() => setSelected(i)}
              >
                {item.type === 'view' ? (
                  <>
                    <span className="cmd-item__icon">{item.icon}</span>
                    <span className="cmd-item__label">{item.label}</span>
                    <kbd className="cmd-item__badge">{VIEWS.findIndex(v => v.id === item.id) + 1}</kbd>
                  </>
                ) : (
                  <>
                    <span className="cmd-item__icon">📌</span>
                    <span className="cmd-item__label">{item.label}</span>
                    <span className="cmd-item__meta mono">{item.stage} · {item.state}</span>
                  </>
                )}
              </div>
            ))
          )}
        </div>
        <div className="cmd-footer">
          <span><kbd>↑↓</kbd> 导航</span>
          <span><kbd>Enter</kbd> 选择</span>
          <span><kbd>ESC</kbd> 关闭</span>
        </div>
      </div>
    </div>
  )
}

import { useMemo, useState } from 'react'
import { prio } from '../constants'

const NODE_W = 148
const NODE_H = 46
const H_GAP = 18
const V_GAP = 36
const PAD = 16

function collectAncestors(task, byId) {
  const out = new Set()
  const stack = [...(task.depends_on || [])]
  const seen = new Set()
  while (stack.length) {
    const cur = stack.pop()
    if (seen.has(cur)) continue
    seen.add(cur)
    if (!byId[cur]) continue
    out.add(cur)
    const t = byId[cur]
    ;(t.depends_on || []).forEach(d => { if (!seen.has(d)) stack.push(d) })
  }
  return out
}

function collectDescendants(taskId, tasks, byId) {
  // reverse adjacency
  const succ = {}
  tasks.forEach(t => {
    ;(t.depends_on || []).forEach(d => {
      if (!byId[d]) return
      if (!succ[d]) succ[d] = []
      succ[d].push(t.id)
    })
  })
  const out = new Set()
  const stack = [...(succ[taskId] || [])]
  const seen = new Set()
  while (stack.length) {
    const cur = stack.pop()
    if (seen.has(cur)) continue
    seen.add(cur)
    if (!byId[cur]) continue
    out.add(cur)
    ;(succ[cur] || []).forEach(n => { if (!seen.has(n)) stack.push(n) })
  }
  return out
}

function kahnLayers(nodeIds, byId) {
  const idSet = new Set(nodeIds)
  const succ = {}
  const indeg = {}
  nodeIds.forEach(id => { succ[id] = []; indeg[id] = 0 })
  nodeIds.forEach(id => {
    const t = byId[id]
    if (!t) return
    ;(t.depends_on || []).forEach(d => {
      if (!idSet.has(d)) return
      indeg[id] += 1
      succ[d].push(id)
    })
  })
  const depth = {}
  let frontier = nodeIds.filter(id => indeg[id] === 0)
  let d = 0
  const layerMap = {}
  while (frontier.length) {
    const next = []
    frontier.forEach(id => {
      depth[id] = d
      if (!layerMap[d]) layerMap[d] = []
      layerMap[d].push(id)
      ;(succ[id] || []).forEach(ch => {
        indeg[ch] -= 1
        if (indeg[ch] === 0) next.push(ch)
      })
    })
    frontier = next
    d += 1
  }
  // nodes in cycles (indeg>0) get deepest layer+1
  const leftover = nodeIds.filter(id => depth[id] === undefined)
  if (leftover.length) {
    const maxD = Math.max(...Object.keys(layerMap).map(Number), -1)
    leftover.forEach(id => {
      depth[id] = maxD + 1
      if (!layerMap[maxD + 1]) layerMap[maxD + 1] = []
      layerMap[maxD + 1].push(id)
    })
  }
  const layers = Object.keys(layerMap).sort((a, b) => +a - +b).map(k => layerMap[k])
  return { layers, depth }
}

// eslint-disable-next-line max-lines-per-function
export default function DependencyGraph({ task, tasks, onOpen }) {
  const [hovered, setHovered] = useState(null)
  const [selected, setSelected] = useState(null)
  const activeId = hovered || selected || task.id

  const byId = useMemo(() => Object.fromEntries((tasks || []).map(t => [t.id, t])), [tasks])

  const ancestors = useMemo(() => collectAncestors(task, byId), [task, byId])
  const descendants = useMemo(() => collectDescendants(task.id, tasks || [], byId), [task, tasks, byId])

  const missing = useMemo(() => (task.depends_on || []).filter(id => !byId[id]), [task, byId])

  // detect cycle locally (simple DFS on full graph)
  const cycleInfo = useMemo(() => {
    const allIds = (tasks || []).map(t => t.id)
    const WHITE = 0, GRAY = 1, BLACK = 2
    const color = Object.fromEntries(allIds.map(id => [id, WHITE]))
    const stack = []
    let cyc = null
    const dfs = (u) => {
      color[u] = GRAY
      stack.push(u)
      const deps = (byId[u]?.depends_on || [])
      for (const v of deps) {
        if (!byId[v]) continue
        if (color[v] === GRAY) {
          const idx = stack.indexOf(v)
          cyc = [...stack.slice(idx), v]
          return true
        }
        if (color[v] === WHITE && dfs(v)) return true
      }
      stack.pop()
      color[u] = BLACK
      return false
    }
    for (const id of allIds) {
      if (color[id] === WHITE && dfs(id)) break
    }
    return cyc
  }, [tasks, byId])

  const subIds = useMemo(() => {
    const s = new Set([...ancestors, task.id, ...descendants])
    return [...s].filter(id => byId[id])
  }, [ancestors, descendants, task, byId])

  const { layers } = useMemo(() => kahnLayers(subIds, byId), [subIds, byId])

  // missing placeholders are shown as extra top layer
  const hasMissing = missing.length > 0

  // layout positions
  const positions = useMemo(() => {
    const pos = {}
    // missing nodes share a virtual top layer
    if (hasMissing) {
      missing.forEach((mid, i) => {
        pos[mid] = {
          x: PAD + i * (NODE_W + H_GAP),
          y: PAD,
          isMissing: true,
        }
      })
    }
    const yOffset = hasMissing ? (NODE_H + V_GAP + PAD) : PAD
    layers.forEach((layer, li) => {
      const w = layer.length * NODE_W + (layer.length - 1) * H_GAP
      const totalW = Math.max(w, hasMissing ? missing.length * NODE_W + (missing.length - 1) * H_GAP : 0)
      // center each layer
      const startX = PAD + Math.max(0, (totalW - w) / 2)
      const y = yOffset + li * (NODE_H + V_GAP)
      layer.forEach((id, idx) => {
        pos[id] = { x: startX + idx * (NODE_W + H_GAP), y, isMissing: false }
      })
    })
    return pos
  }, [layers, missing, hasMissing])

  const edges = useMemo(() => {
    const out = []
    subIds.forEach(id => {
      const t = byId[id]
      if (!t) return
      ;(t.depends_on || []).forEach(dep => {
        if (positions[dep] && positions[id]) {
          out.push({ from: dep, to: id })
        }
      })
    })
    // edges from missing placeholders
    missing.forEach(mid => {
      if (positions[mid] && positions[task.id]) {
        // already covered if task depends on missing
      }
    })
    return out
  }, [subIds, byId, positions, missing, task])

  const svgW = useMemo(() => {
    let mx = 0
    Object.values(positions).forEach(p => { mx = Math.max(mx, p.x + NODE_W) })
    return Math.max(mx + PAD, 360)
  }, [positions])
  const svgH = useMemo(() => {
    let my = 0
    Object.values(positions).forEach(p => { my = Math.max(my, p.y + NODE_H) })
    return Math.max(my + PAD, 120)
  }, [positions])

  const isAncestor = (id) => ancestors.has(id)
  const isDescendant = (id) => descendants.has(id)

  const connOf = (id) => {
    if (!id) return new Set()
    const s = new Set()
    const t = byId[id]
    if (t) (t.depends_on || []).forEach(d => { if (byId[d] || missing.includes(d)) s.add(d) })
    // downstream
    subIds.forEach(other => {
      if ((byId[other]?.depends_on || []).includes(id)) s.add(other)
    })
    return s
  }
  const connected = activeId ? connOf(activeId) : new Set()

  const nodeClass = (id) => {
    if (id === task.id) return 'is-current'
    if (isAncestor(id)) return 'is-ancestor'
    if (isDescendant(id)) return 'is-descendant'
    return ''
  }

  if (subIds.length === 0 && missing.length === 0) {
    return (
      <div className="dep-graph dep-graph--empty">
        <p className="detail-muted">无依赖关系</p>
      </div>
    )
  }

  return (
    <div className="dep-graph">
      {cycleInfo && (
        <div className="dep-graph__alert dep-graph__alert--cycle" role="alert">
          <b>⚠ 循环依赖</b> {cycleInfo.join(' → ')}
        </div>
      )}
      {missing.length > 0 && (
        <div className="dep-graph__alert dep-graph__alert--missing" role="alert">
          <b>⚠ 依赖缺失</b> {missing.join(', ')} — 这些任务不存在，创建/更新时将被拒绝
        </div>
      )}
      <div className="dep-graph__legend">
        <span className="dep-legend dep-legend--current">当前</span>
        <span className="dep-legend dep-legend--ancestor">前置</span>
        <span className="dep-legend dep-legend--descendant">后置</span>
        {missing.length > 0 && <span className="dep-legend dep-legend--missing">缺失</span>}
        <span className="dep-graph__hint">点击节点跳转 · 悬停高亮上下游</span>
      </div>
      <div className="dep-graph__canvas-wrap">
        <svg width={svgW} height={svgH} viewBox={`0 0 ${svgW} ${svgH}`} className="dep-graph__svg" role="img" aria-label="任务依赖图">
          <defs>
            <marker id="dep-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--ink-faint)" />
            </marker>
            <marker id="dep-arrow-active" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto">
              <path d="M 0 0 L 10 5 L 0 10 z" fill="var(--accent)" />
            </marker>
          </defs>
          {edges.map(e => {
            const a = positions[e.from]
            const b = positions[e.to]
            if (!a || !b) return null
            const x1 = a.x + NODE_W / 2
            const y1 = a.y + NODE_H
            const x2 = b.x + NODE_W / 2
            const y2 = b.y
            const active = activeId && (e.from === activeId || e.to === activeId || connected.has(e.from) || connected.has(e.to))
            // direct line or stepped?
            const mx = (y2 - y1) > V_GAP * 1.5
            if (mx) {
              const midY = (y1 + y2) / 2
              return (
                <path
                  key={`${e.from}->${e.to}`}
                  d={`M ${x1} ${y1} C ${x1} ${midY}, ${x2} ${midY}, ${x2} ${y2}`}
                  className={`dep-edge${active ? ' is-active' : ''}`}
                  markerEnd={active ? 'url(#dep-arrow-active)' : 'url(#dep-arrow)'}
                  fill="none"
                />
              )
            }
            return (
              <line
                key={`${e.from}->${e.to}`}
                x1={x1} y1={y1} x2={x2} y2={y2}
                className={`dep-edge${active ? ' is-active' : ''}`}
                markerEnd={active ? 'url(#dep-arrow-active)' : 'url(#dep-arrow)'}
              />
            )
          })}
          // eslint-disable-next-line complexity
          {Object.entries(positions).map(([id, p]) => {
            const isMissingNode = p.isMissing
            const t = byId[id]
            const title = isMissingNode ? id : (t?.title || id)
            const pr = t ? prio(t.priority) : null
            const hl = activeId === id || connected.has(id)
            return (
              <g
                key={id}
                transform={`translate(${p.x},${p.y})`}
                className={`dep-node ${nodeClass(id)}${hl ? ' is-highlight' : ''}${isMissingNode ? ' is-missing' : ''}`}
                onMouseEnter={() => setHovered(id)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => {
                  if (isMissingNode) return
                  setSelected(id)
                  if (onOpen && t) onOpen(t)
                }}
                role={isMissingNode ? 'img' : 'button'}
                tabIndex={isMissingNode ? -1 : 0}
                aria-label={isMissingNode ? `缺失任务 ${id}` : `任务 ${title}`}
                onKeyDown={e => { if (e.key === 'Enter' && !isMissingNode && onOpen && t) onOpen(t) }}
                style={{ cursor: isMissingNode ? 'not-allowed' : 'pointer' }}
              >
                <rect width={NODE_W} height={NODE_H} rx="10" ry="10" />
                <text x="10" y="18" className="dep-node__title">{title.length > 18 ? title.slice(0, 18) + '…' : title}</text>
                <text x="10" y="32" className="dep-node__meta">
                  {isMissingNode ? '缺失' : `${t?.stage || ''} · ${pr?.label || ''}`}
                </text>
                {!isMissingNode && (
                  <text x={NODE_W - 8} y="32" textAnchor="end" className="dep-node__id">{id}</text>
                )}
              </g>
            )
          })}
        </svg>
      </div>
      <div className="dep-graph__stats">
        <span>前置 {ancestors.size}</span>
        <span>后置 {descendants.size}</span>
        <span>层数 {layers.length + (hasMissing ? 1 : 0)}</span>
        <span>边 {edges.length}</span>
      </div>
    </div>
  )
}

