const decodeMaybe = (s) => { try { return decodeURIComponent(s) } catch { return s } }
const dirOf = (p) => { const s = (p || '').replace(/\\/g, '/'); return s.includes('/') ? s.slice(0, s.lastIndexOf('/')) : '' }
function joinRel(dir, src) {
  const out = (dir || '').split('/').filter(Boolean)
  for (const part of src.split('/')) {
    if (!part || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return out.join('/')
}

const RISK_RE = /(风险|隐患|注意|警告|⚠️?|❗|‼|危险|禁止|必须|关键点|坑|caveat|risk|warning|caution|danger|important)/i
const RISK_TAGS = ['strong', 'em', 'li', 'p', 'blockquote', 'td']

// eslint-disable-next-line complexity
function markRisks(root) {
  if (!root) return 0
  let count = 0
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  const hits = []
  while (walker.nextNode()) {
    const n = walker.currentNode
    if (!n.nodeValue || !n.nodeValue.trim()) continue
    if (n.parentElement?.closest('pre, code, .md-risk')) continue
    if (RISK_RE.test(n.nodeValue)) hits.push(n)
  }
  for (const node of hits) {
    const el = node.parentElement
    if (!el || RISK_TAGS.includes(el.tagName.toLowerCase()) === false) {
      el?.classList?.add('md-risk')
      count++
      continue
    }
    el.classList.add('md-risk')
    count++
  }
  return count
}

function wordCount(text) {
  if (!text) return 0
  const ascii = (text.match(/[a-zA-Z0-9]+/g) || []).length
  const cjk = (text.match(/[\u4e00-\u9fff\u3400-\u4dbf\uf900-\ufaff]/g) || []).length
  return ascii + cjk
}

function readingTime(wc) {
  const min = Math.ceil(wc / 300)
  return min < 1 ? '< 1 分钟' : `~${min} 分钟`
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function DocPanel({ task, onClose }) {
  const [docs, setDocs] = useState(null)
  const [selected, setSelected] = useState(null)
  const [html, setHtml] = useState('')
  const [rawContent, setRawContent] = useState('')
  const [loading, setLoading] = useState(false)
  const [err, setErr] = useState(null)
  const [truncated, setTruncated] = useState(false)
  const [missing, setMissing] = useState(false)
  const [query, setQuery] = useState('')
  const [activeKind, setActiveKind] = useState(null)
  const [toc, setToc] = useState([])
  const [riskCount, setRiskCount] = useState(0)
  const [findQ, setFindQ] = useState('')
  const [findHits, setFindHits] = useState(0)
  const [progress, setProgress] = useState(0)
  const [lightbox, setLightbox] = useState(null)
  // 文档生命周期总览（kind -> {state, states, allowed_next, ...}），缺失不阻塞文档浏览
  const [statusMap, setStatusMap] = useState({})
  // 状态推进：按钮落 POST /doc/{kind}/status，成功后刷新总览与清单
  const [advBusy, setAdvBusy] = useState(false)
  const [advErr, setAdvErr] = useState(null)
  const viewRef = useRef(null)
  // S-4：启用鉴权时 /raw 的图片与链接改走 blob URL，这里统一登记，组件卸载时回收。
  // 不在单次 effect cleanup 里 revoke —— 灯箱直接引用 img.src，提前回收会让放大图失效。
  const rawBlobUrls = useRef([])
  useEffect(() => () => {
    rawBlobUrls.current.forEach(u => { try { URL.revokeObjectURL(u) } catch { /* ignore */ } })
    rawBlobUrls.current = []
  }, [])

  // Esc 归属：只有栈顶浮层响应（Phase 2 D1/C-2）。
  // 图片灯箱是本面板内部的子层，先关灯箱，再关面板。
  const lightboxRef = useRef(lightbox)
  lightboxRef.current = lightbox
  useOverlayStack(() => {
    if (lightboxRef.current) { setLightbox(null); return }
    onClose()
  })

  const select = useCallback((doc) => {
    setSelected(doc); setLoading(true); setErr(null); setHtml(''); setRawContent(''); setToc([]); setFindQ(''); setFindHits(0); setProgress(0)
    const p = doc.source === 'field'
      ? api.getTaskDoc(task.id, doc.kind)
      : api.getTaskFile(task.id, doc.rel_path)
    p.then(r => {
        if (r.binary) {
          // 交付物 / 相关文件可能是二进制（PDF、图片…），不能按文本渲染
          setTruncated(false); setMissing(false); setRawContent('')
          setHtml(`<p class="docpanel__notice">二进制文件（${fmtSize(r.size ?? 0)}），无法按文本预览。</p>`)
          return
        }
        const content = r.content || ''
        setTruncated(!!r.truncated); setMissing(!!r.missing)
        setRawContent(content)
        setHtml(DOMPurify.sanitize(marked.parse(content), { ADD_ATTR: ['target'] }))
      })
      .catch(e => { setErr(e.stack || e.message); setTruncated(false); setMissing(false) })
      .finally(() => setLoading(false))
  }, [task.id])

  useEffect(() => {
    let alive = true
    api.getTaskDocuments(task.id).then(r => { if (!alive) return; const list = r.documents || []; setDocs(list); if (list.length) select(list[0]) })
      .catch(e => { if (alive) { setDocs([]); setErr(e.message) } })
    // 生命周期总览：拿 states 全序列 + 合法后继，用于状态徽标与推进条
    api.getDocStatuses(task.id)
      .then(r => { if (alive) setStatusMap(r.statuses || {}) })
      .catch(() => { if (alive) setStatusMap({}) })
    return () => { alive = false }
  }, [task.id, select])

  useEffect(() => {
    const root = viewRef.current
    if (!root || !html) return
    // S-4 通道 ④：启用鉴权时标签请求带不上 Authorization，/raw 改走 fetch + blob URL。
    // 未启用鉴权时 authed=false，下面两条分支完全保持原行为。
    const authed = api.hasToken()
    root.querySelectorAll('pre code').forEach(b => { try { hljs.highlightElement(b) } catch { /* 高亮失败不阻塞 */ } })
    root.querySelectorAll('a[href]').forEach(a => {
      a.target = '_blank'
      a.rel = 'noopener noreferrer'
      const rawHref = a.getAttribute('href') || ''
      // 相对链接指向 workspace 内文件 → 改写到 /raw，否则浏览器会请求前端静态路径 → 404
      if (rawHref && !rawHref.startsWith('#') && !rawHref.includes('?') && !ABS_SRC_RE.test(rawHref)) {
        const baseDir = selected && selected.dir != null ? selected.dir : dirOf(selected && selected.rel_path)
        const resolved = joinRel(baseDir, decodeMaybe(rawHref))
        a.href = api.rawFileUrl(task.id, resolved)
        if (authed) {
          // href 保留 /raw 作为兜底；异步换成 blob URL，点击时浏览器按原语义打开
          api.rawFileBlobUrl(task.id, resolved)
            .then(u => { rawBlobUrls.current.push(u); if (a.isConnected) a.href = u })
            .catch(() => { /* 保留 /raw 兜底 */ })
        }
        // 相对 .md 链接在面板内直接打开目标文档（拦截点击；href 保留 /raw 作为兜底）
        if (/\.(md|markdown)$/i.test(resolved)) {
          a.addEventListener('click', (e) => {
            e.preventDefault(); e.stopPropagation()
            select({
              name: resolved.split('/').pop() || resolved,
              rel_path: resolved,
              kind: 'file', source: 'navigated', dir: dirOf(resolved),
            })
          })
        }
      }
    })
    root.querySelectorAll('img').forEach(img => {
      // 相对引用的图片指向 workspace 内的原始文件，否则浏览器会请求前端静态路径 → 404
      const rawSrc = img.getAttribute('src') || ''
      if (rawSrc && !ABS_SRC_RE.test(rawSrc)) {
        const baseDir = selected && selected.dir != null ? selected.dir : dirOf(selected && selected.rel_path)
        const rel = joinRel(baseDir, decodeMaybe(rawSrc))
        if (authed) {
          api.rawFileBlobUrl(task.id, rel)
            .then(u => { rawBlobUrls.current.push(u); if (img.isConnected) img.src = u })
            .catch(() => { /* 保留原始 src 作为失败提示 */ })
        } else {
          img.src = api.rawFileUrl(task.id, rel)
        }
      }
      img.loading = 'lazy'; img.style.maxWidth = '100%'; img.style.height = 'auto'
      img.style.cursor = 'zoom-in'
      img.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); setLightbox(img.src) })
    })
    root.querySelectorAll('table').forEach(t => { if (!t.parentElement.classList.contains('md-table-wrap')) { const w = document.createElement('div'); w.className = 'md-table-wrap'; t.before(w); w.appendChild(t) } })
    const rc = markRisks(root)
    setRiskCount(rc)
    const hs = [...root.querySelectorAll('h1,h2,h3')]
    setToc(hs.map((h, i) => { if (!h.id) h.id = 'mdh-' + i; return { id: h.id, text: h.textContent, level: Number(h.tagName[1]) } }))
  }, [html, selected, task.id, select])

  useEffect(() => {
    const root = viewRef.current
    if (!root) return
    root.querySelectorAll('mark.md-find').forEach(m => { const p = m.parentNode; p.replaceChild(document.createTextNode(m.textContent), m); p.normalize() })
    if (!findQ.trim()) { setFindHits(0); return }
    const needle = findQ.toLowerCase()
    let hits = 0
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
    const targets = []
    while (walker.nextNode()) {
      const n = walker.currentNode
      if (n.nodeValue && n.nodeValue.toLowerCase().includes(needle) && !n.parentElement.closest('.md-find')) targets.push(n)
    }
    for (const node of targets) {
      const text = node.nodeValue
      const lower = text.toLowerCase()
      const frag = document.createDocumentFragment()
      let idx = 0
      while (true) {
        const at = lower.indexOf(needle, idx)
        if (at === -1) break
        frag.appendChild(document.createTextNode(text.slice(idx, at)))
        const mk = document.createElement('mark')
        mk.className = 'md-find'
        mk.textContent = text.slice(at, at + findQ.length)
        frag.appendChild(mk)
        idx = at + findQ.length
        hits++
        if (hits > 500) break
      }
      frag.appendChild(document.createTextNode(text.slice(idx)))
      node.parentNode.replaceChild(frag, node)
    }
    setFindHits(hits)
  }, [findQ, html])

  useEffect(() => {
    const el = viewRef.current
    if (!el) return
    const onScroll = () => {
      const total = el.scrollHeight - el.clientHeight
      setProgress(total > 0 ? Math.min(100, Math.round(el.scrollTop / total * 100)) : 0)
    }
    el.addEventListener('scroll', onScroll, { passive: true })
    return () => el.removeEventListener('scroll', onScroll)
  }, [])

  const goTo = (id) => { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' }) }

  const jumpFind = (dir) => {
    const marks = [...(viewRef.current?.querySelectorAll('mark.md-find') || [])]
    if (!marks.length) return
    const cur = marks.findIndex(m => m.classList.contains('is-cur'))
    const next = dir > 0 ? Math.min(cur + 1, marks.length - 1) : Math.max(cur - 1, 0)
    marks.forEach(m => m.classList.remove('is-cur'))
    marks[next]?.classList.add('is-cur')
    marks[next]?.scrollIntoView({ behavior: 'smooth', block: 'center' })
  }

  const printDoc = () => {
    const content = viewRef.current?.querySelector('.md')?.innerHTML
    if (!content) return
    const w = window.open('', '_blank')
    w.document.write(`<!DOCTYPE html><html><head><title>${selected?.name || '文档'}</title>
      <style>body{font-family:system-ui,sans-serif;max-width:800px;margin:40px auto;padding:0 20px;line-height:1.7;color:#222}
      pre{background:#f5f5f5;padding:12px;border-radius:6px;overflow-x:auto}
      code{font-size:0.9em}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:6px 10px}
      img{max-width:100%}blockquote{border-left:3px solid #ccc;margin:0;padding-left:16px;color:#555}
      @media print{body{margin:0}pre{white-space:pre-wrap}}</style></head><body>`)
    w.document.write(content)
    w.document.close()
    w.print()
  }

  const all = docs || []
  const q = query.trim().toLowerCase()
  const filtered = q ? all.filter(d => d.name.toLowerCase().includes(q) || d.rel_path.toLowerCase().includes(q)) : all

  // 顶部「切换类型」标签：列出清单里实际存在的文档类型（按 KIND_META 顺序）
  const kindsPresent = useMemo(() => {
    const counts = {}
    for (const d of all) counts[d.kind] = (counts[d.kind] || 0) + 1
    return Object.keys(counts)
      .sort((a, b) => kindMeta(a).order - kindMeta(b).order)
      .map(k => ({ kind: k, label: kindMeta(k).label, count: counts[k] }))
  }, [all])

  // 两级分组：category（链内文档 / 交付物 / 参考文件）→ kind（受顶部类型筛选影响）
  const catBuckets = {}
  for (const d of filtered) {
    if (activeKind && d.kind !== activeKind) continue
    const ck = categoryOf(d)
    if (!catBuckets[ck]) catBuckets[ck] = { key: ck, meta: CATEGORY_META[ck] || { label: ck, order: 9 }, kinds: {} }
    const kg = catBuckets[ck].kinds
    if (!kg[d.kind]) kg[d.kind] = { meta: kindMeta(d.kind), items: [] }
    kg[d.kind].items.push(d)
  }
  const sortedCategories = Object.values(catBuckets)
    .sort((a, b) => a.meta.order - b.meta.order)
    .map(c => {
      const kindGroups = Object.values(c.kinds).sort((a, b) => a.meta.order - b.meta.order)
      return { ...c, kindGroups, count: kindGroups.reduce((n, g) => n + g.items.length, 0) }
    })

  const catCounts = useMemo(() => {
    const c = { doc: 0, deliverable: 0, reference: 0 }
    for (const d of all) { const k = categoryOf(d); c[k] = (c[k] || 0) + 1 }
    return c
  }, [all])

  const switchKind = (kind) => {
    setActiveKind(kind)
    if (kind) {
      const first = all.find(d => d.kind === kind)
      if (first) select(first)
    }
  }

  const wc = wordCount(rawContent)

  // 选中文档的生命周期：状态以清单条目为准（回退总览），赛道全序列来自总览接口
  const selStatus = selected ? (stateOfDoc(selected) || stateOfStatus(statusMap[selected.kind])) : null
  const selTrack = selected ? lifecycleTrack((statusMap[selected.kind] || {}).states, selStatus) : []

  // 状态推进：合法后继来自总览接口 allowed_next（与后端 doc_lifecycle 同源）。
  // 只有链内文档（source=field）且该 kind 有生命周期才可推进；未登记（无落盘文件）时禁用。
  const selEntry = selected ? statusMap[selected.kind] : null
  const allowedNext = (selEntry && selEntry.allowed_next) || []
  const canAdvance = !!(selected && selected.source === 'field' && selEntry)
  const advDisabled = advBusy || canAdvance === false || selEntry?.has_doc === false

  const advanceDoc = async (target) => {
    if (!selected || advBusy) return
    setAdvBusy(true); setAdvErr(null)
    try {
      await api.setDocStatus(task.id, selected.kind, { state: target })
      const [st, docsR] = await Promise.all([
        api.getDocStatuses(task.id),
        api.getTaskDocuments(task.id),
      ])
      setStatusMap(st.statuses || {})
      const list = docsR.documents || []
      setDocs(list)
      const cur = list.find(d => d.rel_path === selected.rel_path)
      if (cur) setSelected(cur)
    } catch (e) {
      // 质量门 422 的 detail 是 {message, quality}，优先取人话 message
      const d = e && e.detail
      setAdvErr((d && d.message) || e.message)
    } finally {
      setAdvBusy(false)
    }
  }

  return (
    <div className="overlay docpanel-overlay" onClick={onClose}>
      <div className="docpanel" role="dialog" aria-modal="true" aria-label="文档浏览" onClick={e => e.stopPropagation()}>
        <header className="docpanel__head">
          <span className="docpanel__eyebrow">文档浏览</span>
          <h2 className="docpanel__title">{task.title}</h2>
          <span className="docpanel__sub docpanel__ws">{task.workspace ? task.workspace : '无工作区'}</span>
          <div className="docpanel__head-actions">
            {selected && <button className="btn btn--ghost btn--xs" onClick={printDoc} title="打印 / 导出 PDF">🖨 打印</button>}
            <button className="modal__close" onClick={onClose} aria-label="关闭">×</button>
          </div>
        </header>
        <div className="docpanel__toolbar">
          <input className="docpanel__search-input" placeholder="搜索文档名 / 路径" value={query} onChange={e => setQuery(e.target.value)} />
          <input className="docpanel__search-input docpanel__find-input" placeholder="全文查找…" value={findQ} onChange={e => setFindQ(e.target.value)}
                 onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); jumpFind(e.shiftKey ? -1 : 1) } }} />
          {findQ && <span className="docpanel__find-count">{findHits} 处命中（Enter ↴ / Shift+Enter ↰）</span>}
          <div className="docpanel__kinds">
            <button className={`docpanel__kindtab${activeKind ? '' : ' is-active'}`} onClick={() => switchKind(null)}>全部<span>{all.length}</span></button>
            {kindsPresent.map(k => (
              <button key={k.kind} className={`docpanel__kindtab${activeKind === k.kind ? ' is-active' : ''}`} onClick={() => switchKind(k.kind)}>
                {k.label}<span>{k.count}</span>
              </button>
            ))}
          </div>
          <span className="docpanel__count">{docs ? `${docs.length} 篇 · 文档 ${catCounts.doc} / 交付物 ${catCounts.deliverable} / 参考 ${catCounts.reference}` : '加载中…'}{riskCount > 0 && ` · ${riskCount} 处风险标记`}</span>
        </div>
        <div className="docpanel__body">
          <nav className="docpanel__list">
            {docs === null && <p className="detail-muted">加载中…</p>}
            {docs && docs.length === 0 && <p className="detail-muted">该任务无关联文档</p>}
            {sortedCategories.map(cat => (
              <div key={cat.key} className="docpanel__cat">
                <div className="docpanel__cat-title">
                  {cat.meta.label}<span className="docpanel__cat-count">{cat.count}</span>
                  {cat.meta.hint && <span className="docpanel__cat-hint">{cat.meta.hint}</span>}
                </div>
                {cat.kindGroups.map(g => (
                  <div key={g.meta.group} className="docpanel__group">
                    <div className="docpanel__group-title">{g.meta.group}</div>
                    {g.items.map(d => {
                      const km = kindMeta(d.kind)
                      const st = stateOfDoc(d)
                      return (
                        <button key={d.rel_path} className={`docpanel__item${selected?.rel_path === d.rel_path ? ' is-active' : ''}`} onClick={() => select(d)}>
                          <span className={`docpanel__kind docpanel__kind--${d.kind}`}>{km.label}</span>
                          <span className="docpanel__name">
                            {d.name}
                            {st && <span className={`docpanel__docstate docpanel__docstate--${docStateTone(st)}`}
                                         title={`生命周期状态：${docStateLabel(st)}`}>{docStateLabel(st)}</span>}
                          </span>
                          {d.exists === false && <span className="docpanel__missing" title="路径已登记但文件不存在">缺失</span>}
                          <span className="docpanel__src">{sourceLabel(d.source)}</span>
                          <span className="docpanel__sub mono">{d.rel_path}{d.size != null ? ` · ${fmtSize(d.size)}` : ''}</span>
                        </button>
                      )
                    })}
                  </div>
                ))}
              </div>
            ))}
            {docs && docs.length > 0 && filtered.length === 0 && <p className="detail-muted">无匹配「{query}」</p>}
          </nav>
          <aside className="docpanel__toc">
            <div className="docpanel__group-title">目录</div>
            {toc.length === 0 && <p className="detail-muted">无标题</p>}
            {toc.map(t => (
              <button key={t.id} className={`docpanel__toc-item lv${t.level}`} onClick={() => goTo(t.id)} title={t.text}>{t.text}</button>
            ))}
          </aside>
          <article className={`docpanel__view${progress > 0 ? ' has-progress' : ''}`} ref={viewRef}>
            {selected && (
              <div className="docpanel__meta-bar">
                {rawContent && <span>{wc} 字 · {readingTime(wc)}</span>}
                {selStatus && (
                  <span className={`docpanel__docstate docpanel__docstate--${docStateTone(selStatus)}`}
                        title={`生命周期状态：${docStateLabel(selStatus)}`}>
                    生命周期：{docStateLabel(selStatus)}
                  </span>
                )}
                {/* 该 kind 有生命周期就显示赛道：未落状态的文档全节点为「待推进」，
                    这样 8 类生命周期在 UI 上都可见，而不是只有已落状态的那几个。 */}
                {selTrack.length > 1 && (
                  <span className="docpanel__flow">
                    {selTrack.map((n, i) => (
                      <span key={n.state} className="docpanel__flow-node">
                        {i > 0 && <span className="docpanel__flow-arrow">→</span>}
                        <span className={`docpanel__flow-label is-${n.phase} tone-${n.tone}`}
                              title={`${n.label}${n.phase === 'current' ? '（当前）' : ''}`}>
                          {n.label}
                        </span>
                      </span>
                    ))}
                  </span>
                )}
                {canAdvance && allowedNext.length > 0 && (
                  <span className="docpanel__advance">
                    {allowedNext.map(st => (
                      <button key={st} className="btn btn--ghost btn--xs" disabled={advDisabled}
                              title={selEntry?.has_doc === false
                                ? '文档未登记（没有落盘文件），先登记路径或写入文档后再推进'
                                : `把「${kindMeta(selected.kind).label}」状态推进到「${docStateLabel(st)}」`}
                              onClick={() => advanceDoc(st)}>
                        {advBusy ? '…' : `→ ${docStateLabel(st)}`}
                      </button>
                    ))}
                  </span>
                )}
                {truncated && <span className="docpanel__meta-warn">内容已截断</span>}
              </div>
            )}
            {advErr && <div className="docpanel__notice docpanel__notice--err">推进失败：{advErr}</div>}
            {loading && <div className="docpanel__loading"><span className="spinner" /> 渲染中…</div>}
            {err && <div className="docpanel__notice docpanel__notice--err">{err}</div>}
            {!loading && !err && missing && <div className="docpanel__notice docpanel__notice--warn">文档缺失：{selected && selected.rel_path}</div>}
            {!loading && !err && !missing && truncated && <div className="docpanel__notice docpanel__notice--warn">内容已截断（超过 20 万字符），仅显示前部分。</div>}
            {!loading && !err && !missing && html && <div className="md" dangerouslySetInnerHTML={{ __html: html }} />}
            {!loading && !err && !missing && !html && docs && <p className="detail-muted">请选择左侧文档。</p>}
            {!loading && html && progress > 3 && (
              <button className="docpanel__backtop" onClick={() => viewRef.current?.scrollTo({ top: 0, behavior: 'smooth' })} aria-label="返回顶部">↑ 顶部 · {progress}%</button>
            )}
          </article>
        </div>
      </div>
      {lightbox && (
        <div className="lightbox-overlay" onClick={() => setLightbox(null)}>
          <img src={lightbox} alt="preview" className="lightbox-img" />
          <button className="lightbox-close" onClick={() => setLightbox(null)}>×</button>
        </div>
      )}
    </div>
  )
}

// Enhanced Idea Search Component with Filters and Scoring
import { useState, useEffect, useCallback, useMemo } from 'react'
import { api } from '../api'
import { parseUtc } from '../constants'

// eslint-disable-next-line complexity, max-lines-per-function
function IdeaSearch({ ideas: initialIdeas, onSelect, onRefresh: _onRefresh }) {
  const [query, setQuery] = useState('')
  const [filters, setFilters] = useState({
    status: [],
    idea_type: '',
    category: '',
    project: '',
    labels: [],
    date_from: '',
    date_to: '',
    min_score: 0,
  })
  const [sortBy, setSortBy] = useState('updated_at')
  const [sortOrder, setSortOrder] = useState('desc')
  const [page, setPage] = useState(1)
  const [pageSize] = useState(20)
  const [results, setResults] = useState({ ideas: [], count: 0, total_pages: 1 })
  const [loading, setLoading] = useState(false)
  const [showFilters, setShowFilters] = useState(false)
  const [showScores, setShowScores] = useState(false)
  const [scores, setScores] = useState({})
  const [error, setError] = useState(null)

  // Debounced search
  const _debouncedSearch = useMemo(
    () => {
      let timeoutId
      return (fn) => {
        clearTimeout(timeoutId)
        timeoutId = setTimeout(fn, 300)
      }
    },
    []
  )

  // eslint-disable-next-line complexity
  const performSearch = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const payload = {
        query: query.trim() || null,
        status: filters.status.length ? filters.status : null,
        idea_type: filters.idea_type || null,
        category: filters.category || null,
        project: filters.project || null,
        labels: filters.labels.length ? filters.labels : null,
        date_from: filters.date_from || null,
        date_to: filters.date_to || null,
        min_score: filters.min_score || null,
        sort_by: sortBy,
        sort_order: sortOrder,
        page,
        page_size: pageSize,
      }
      const res = await api.post('/api/v1/ideas/search', payload)
      setResults(res)
      if (res.ideas?.length > 0) {
        // Fetch scores for results
        try {
          const scoresRes = await api.post('/api/v1/ideas/scores', {
            idea_ids: res.ideas.map(i => i.id),
          })
          setScores(scoresRes.scores || {})
        } catch (e) {
          console.warn('Failed to fetch scores', e)
        }
      }
    } catch (e) {
      setError(e.message || '搜索失败')
    } finally {
      setLoading(false)
    }
  }, [query, filters, sortBy, sortOrder, page, pageSize])

  useEffect(() => {
    performSearch()
  }, [performSearch])

  // Also load scores for initial ideas if no search
  useEffect(() => {
    if (!query && initialIdeas?.length) {
      const load = async () => {
        try {
          const res = await api.post('/api/v1/ideas/scores', {
            idea_ids: initialIdeas.map(i => i.id),
          })
          setScores(res.scores || {})
        } catch (e) {
          console.warn('Failed to fetch initial scores', e)
        }
      }
      load()
    }
  }, [initialIdeas])

  const toggleFilter = (key, value) => {
    setFilters(prev => {
      const arr = prev[key] || []
      const idx = arr.indexOf(value)
      if (idx >= 0) {
        return { ...prev, [key]: arr.filter(v => v !== value) }
      }
      return { ...prev, [key]: [...arr, value] }
    })
  }

  const clearFilters = () => {
    setFilters({
      status: [],
      idea_type: '',
      category: '',
      project: '',
      labels: [],
      date_from: '',
      date_to: '',
      min_score: 0,
    })
    setPage(1)
  }

  const getScoreInfo = (ideaId) => {
    return scores[ideaId] || { score: 0, factors: {}, recommendation: 'unknown' }
  }

  const getScoreColor = (score) => {
    if (score >= 8) return 'ok'
    if (score >= 4) return 'live'
    if (score >= 2) return 'warning'
    return 'dim'
  }

  return (
    <div className="idea-search">
      <div className="idea-search__header">
        <h3>🔍 想法搜索与评分</h3>
        <div className="idea-search__header-actions">
          <label className="checkbox-inline">
            <input
              type="checkbox"
              checked={showScores}
              onChange={e => setShowScores(e.target.checked)}
            />
            显示优先级评分
          </label>
          <label className="checkbox-inline">
            <input
              type="checkbox"
              checked={showFilters}
              onChange={e => setShowFilters(e.target.checked)}
            />
            高级筛选
          </label>
        </div>

        {/* Search Bar */}
        <div className="idea-search__bar">
          <input
            type="text"
            className="inp inp--lg"
            placeholder="搜索标题、描述... (回车搜索)"
            value={query}
            onChange={e => setQuery(e.target.value)}
            onKeyDown={e => { if (e.key === 'Enter') performSearch() }}
          />
          <button className="btn btn--primary" onClick={performSearch} disabled={loading}>
            {loading ? '搜索中…' : '搜索'}
          </button>
          {filters.status.length || filters.idea_type || filters.labels.length || filters.min_score > 0 ? (
            <button className="btn btn--ghost" onClick={clearFilters}>清除筛选</button>
          ) : null}
        </div>

        {/* Advanced Filters */}
        {showFilters && (
          <div className="idea-search__filters">
            <div className="filter-row">
              <div className="filter-group">
                <label>状态</label>
                <div className="filter-chips">
                  {['new', 'fermenting', 'formed', 'broken_down', 'archived', 'cancelled'].map(s => (
                    <button
                      key={s}
                      className={`filter-chip${filters.status.includes(s) ? ' is-on' : ''}`}
                      onClick={() => toggleFilter('status', s)}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <div className="filter-group">
                <label>类型</label>
                <select className="inp" value={filters.idea_type} onChange={e => setFilters(p => ({ ...p, idea_type: e.target.value }))}>
                  <option value="">全部</option>
                  <option value="idea">想法</option>
                  <option value="adr">ADR</option>
                </select>
              </div>

              <div className="filter-group">
                <label>项目</label>
                <input
                  className="inp"
                  placeholder="项目名"
                  value={filters.project}
                  onChange={e => setFilters(p => ({ ...p, project: e.target.value }))}
                />
              </div>

              <div className="filter-group">
                <label>标签</label>
                <input
                  className="inp"
                  placeholder="标签 (逗号分隔)"
                  value={filters.labels.join(', ')}
                  onChange={e => setFilters(p => ({ ...p, labels: e.target.value.split(',').map(s => s.trim()).filter(Boolean) }))}
                />
              </div>

              <div className="filter-group">
                <label>最低评分</label>
                <input
                  type="number"
                  className="inp"
                  step="0.1"
                  min="0"
                  max="20"
                  value={filters.min_score}
                  onChange={e => setFilters(p => ({ ...p, min_score: parseFloat(e.target.value) || 0 }))}
                />
              </div>

              <div className="filter-group">
                <label>日期范围</label>
                <div className="filter-date-range">
                  <input
                    type="date"
                    className="inp"
                    value={filters.date_from}
                    onChange={e => setFilters(p => ({ ...p, date_from: e.target.value }))}
                    placeholder="开始"
                  />
                  <span>至</span>
                  <input
                    type="date"
                    className="inp"
                    value={filters.date_to}
                    onChange={e => setFilters(p => ({ ...p, date_to: e.target.value }))}
                    placeholder="结束"
                  />
                </div>
              </div>

              <div className="filter-group">
                <label>排序</label>
                <div className="filter-sort">
                  <select className="inp inp--sm" value={sortBy} onChange={e => setSortBy(e.target.value)}>
                    <option value="updated_at">更新时间</option>
                    <option value="created_at">创建时间</option>
                    <option value="title">标题</option>
                    <option value="status">状态</option>
                  </select>
                  <select className="inp inp--sm" value={sortOrder} onChange={e => setSortOrder(e.target.value)}>
                    <option value="desc">降序</option>
                    <option value="asc">升序</option>
                  </select>
                </div>
              </div>
            </div>
          </div>
        )}

        {error && <div className="errorbar" role="alert"><span>▲</span><span>{error}</span><button onClick={() => setError(null)}>×</button></div>}

        {/* Results */}
        <div className="idea-search__results">
          {loading && <div className="search-loading">搜索中…</div>}

          {!loading && (!results.ideas || results.ideas.length === 0) && (
            <div className="search-empty">
              没有找到匹配的想法。尝试调整筛选条件或搜索关键词。
            </div>
          )}

          <div className="idea-search__list">
            // eslint-disable-next-line complexity
            {(results.ideas || []).map(idea => {
              const scoreInfo = getScoreInfo(idea.id)
              return (
                <div key={idea.id} className={`idea-search__item${onSelect ? ' clickable' : ''}`} onClick={() => onSelect?.(idea)}>
                  <div className="idea-search__item-main">
                    <div className="idea-search__item-title">
                      <span className={`badge badge--${(idea.idea_type === 'adr' ? { proposed: 'live', accepted: 'ok', rejected: 'dim', deprecated: 'dim', superseded: 'dim' }[idea.adr_status] || 'live' : { new: 'dim', fermenting: 'live', formed: 'ok', broken_down: 'ok', archived: 'dim', cancelled: 'danger' }[idea.status] || 'dim')}`}>
                        {idea.idea_type === 'adr' ? (idea.adr_status === 'proposed' ? 'ADR提议' : idea.adr_status === 'accepted' ? 'ADR接受' : idea.adr_status === 'rejected' ? 'ADR拒绝' : idea.adr_status === 'deprecated' ? 'ADR废弃' : 'ADR取代') : ({ new: '记录中', fermenting: '发酵中', formed: '已成形', broken_down: '已拆解', archived: '已归档', cancelled: '已取消' }[idea.status] || idea.status)}
                      </span>
                      <span className="idea-search__item-title-text">{idea.title}</span>
                      {showScores && scoreInfo.score > 0 && (
                        <span className={`score-badge score-badge--${getScoreColor(scoreInfo.score)}`}>
                          {scoreInfo.score.toFixed(1)}
                        </span>
                      )}
                    </div>
                    <div className="idea-search__item-meta">
                      {idea.project && <span className="tag tag--project">{idea.project}</span>}
                      {idea.labels?.map(l => <span key={l} className="tag">{l}</span>)}
                      <span className="mono">{parseUtc(idea.updated_at).toLocaleDateString()}</span>
                    </div>
                    {showScores && scoreInfo.factors && (
                      <div className="score-breakdown">
                        <span className="score-factor">触达: {scoreInfo.factors.reach}</span>
                        <span className="score-factor">影响: {scoreInfo.factors.impact}</span>
                        <span className="score-factor">置信: {scoreInfo.factors.confidence}</span>
                        <span className="score-factor">工作量: {scoreInfo.factors.effort}</span>
                        <span className={`score-recommendation score-recommendation--${scoreInfo.recommendation}`}>
                          {scoreInfo.recommendation}
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>

          {/* Pagination */}
          {results.total_pages > 1 && (
            <div className="search-pagination">
              <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1}>
                上一页
              </button>
              <span className="pagination-info">
                第 {page} / {results.total_pages} 页，共 {results.count} 条
              </span>
              <button className="btn btn--ghost btn--sm" onClick={() => setPage(p => Math.min(results.total_pages, p + 1))} disabled={page >= results.total_pages}>
                下一页
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

