/** 单日素材抽屉：来源计数 + 每源前 3 条标题（折叠，默认不铺开）。 */
function ObservationsDrawer({ obs }) {
  const [open, setOpen] = useState(false)
  if (!obs) return <div className="detail-muted" style={{ fontSize: 12, marginTop: 6 }}>今日无原始抓取</div>
