              {junk.length > 0 &&
                <span className="detail-muted" style={{ fontSize: 11, marginLeft: 8 }}>
                  已过滤 {junk.length} 条无效 token 选题
                </span>}
            </>)}
      </div>

      {/* 洞察卡列表 */}
      <div style={{ marginTop: 8 }}>
        {day.insights.length === 0
