  result:       { label: '执行进展',   tone: 'ok' },
  verification: { label: '验证',       tone: 'ok' },
  discussion:   { label: '讨论',       tone: 'muted' },
  review:       { label: '评审',       tone: 'warn' },
  plan:         { label: '计划',       tone: 'muted' },
  design:       { label: '设计',       tone: 'muted' },
  created:      { label: '创建',       tone: 'muted' },
  claimed:      { label: '认领',       tone: 'live' },
  heartbeat:    { label: '心跳',       tone: 'muted' },
  retry:        { label: '重试',       tone: 'warn' },
  error:        { label: '错误',       tone: 'danger' },
  failure:      { label: '失败',       tone: 'danger' },
  done:         { label: '完成',       tone: 'ok' },
  cancelled:    { label: '取消',       tone: 'muted' },
  // 窄门禁（d468e633 FR-5）：提交被拦截
  rejected:     { label: '已拦截',     tone: 'danger' },
}

const HIST_TEXT_KEYS = ['raw', 'content', 'text', 'message', 'summary', 'result', 'detail', 'note']

// payload 落库时是 JSON 字符串，常见形态：
//   '{"raw": "…\\u9700…"}' / '"…中文…"' / 嵌套双层编码 / 纯文本
// 逐层解包 + 解转义，还原成人能直接读的文字。
// eslint-disable-next-line complexity
function histPayload(p) {
  if (p == null) return { text: '', json: false }
  let v = p
  for (let i = 0; i < 4 && typeof v === 'string'; i++) {
    const s = v.trim()
    if (!(s.startsWith('{') || s.startsWith('[') || s.startsWith('"'))) break
    try {
      v = JSON.parse(s)
    } catch {
      break
    }
  }
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    const key = HIST_TEXT_KEYS.find(k => typeof v[k] === 'string' && v[k].trim())
    if (key) {
      v = v[key]
    } else {
      return { text: JSON.stringify(v, null, 2), json: true }
    }
  } else if (Array.isArray(v)) {
    return { text: JSON.stringify(v, null, 2), json: true }
  }
  let s = String(v)
  // JSON 解析失败时残留的 \uXXXX 转义：补引号/换行后再按 JSON 解一次
  if (/\\u[0-9a-fA-F]{4}/.test(s)) {
    try {
      s = JSON.parse(`"${s.replace(/\r/g, '\\r').replace(/\n/g, '\\n').replace(/"/g, '\\"')}"`)
    } catch {
      s = s.replace(/\\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    }
  }
  return { text: s.trim(), json: false }
}

// 验收标准按行拆成可扫读列表；单行则整段展示
function acceptanceLines(text) {
  if (!text) return []
  return String(text)
    .split(/\r?\n/)
    .map(s => s.replace(/^[\s]*[-*•·]\s*/, '').replace(/^\d+[.)、]\s*/, '').trim())
    .filter(Boolean)
}

const STAGE_FLOW = ['brainstorming', 'design', 'planning', 'ready', 'implementing', 'review', 'done']

function completionOf(task) {
  const subs = task.subtasks || []
  if (subs.length > 0) {
    const done = subs.filter(s => s.status === 'done').length
    return { pct: Math.round(done / subs.length * 100), label: `${done}/${subs.length}`, source: '子任务' }
  }
  const sidx = STAGE_FLOW.indexOf(task.stage)
  if (sidx >= 0) {
    return {
      pct: Math.round((sidx + 1) / STAGE_FLOW.length * 100),
      label: `${sidx + 1}/${STAGE_FLOW.length}`,
      source: '阶段',
    }
  }
  if (task.state === 'completed') return { pct: 100, label: '完成', source: '状态' }
  if (task.state === 'failed') return { pct: 0, label: '失败', source: '状态' }
  return { pct: 0, label: '—', source: '—' }
}

const TAB_DEFS = [
  { id: 'blockers', label: '就绪度' },
  { id: 'workstream', label: '工作流' },
  { id: 'deps',     label: '依赖' },
  { id: 'subtasks', label: '清单' },
  { id: 'disc',     label: '讨论' },
  { id: 'activity', label: '动态' },
]

// 就绪度三层：流程约束（推不动）/ 执行输入（做了也白做）/ 执行风险（知道再决定）
const READY_LAYERS = [
  { id: 'flow',  label: '流程约束', hint: '这些不解决，任务根本动不了' },
  { id: 'input', label: '执行输入', hint: '数据、参数、规则没齐，干出来大概率要返工' },
  { id: 'risk',  label: '执行风险', hint: '不挡流程，但会影响怎么做' },
]

// 单条执行历史：类型标签 + 时间 + 解码后的正文（过长折叠可展开）
function HistRow({ h }) {
  const [open, setOpen] = useState(false)
  const { text, json } = histPayload(h.payload)
  const lines = text ? text.split('\n').length : 0
  const long = text.length > 360 || lines > 6
  const meta = HIST_TYPE_META[h.type] || { label: h.type || '记录', tone: 'muted' }
  return (
    <div className="hist-row">
      <span className="hist-row__dot" aria-hidden="true" />
      <div className="hist-row__body">
        <div className="hist-row__head">
          <span className={`chip chip--composite chip--${meta.tone}`}>{meta.label}</span>
          <span className="hist-row__at mono">{fmtDate(h.at)}</span>
        </div>
        {text && (
          <div className={`hist-row__text${json ? ' is-json' : ''}${long && !open ? ' is-clamped' : ''}`}>
            {text}
          </div>
        )}
        {long && (
          <button type="button" className="hist-row__toggle" onClick={() => setOpen(o => !o)}>
            {open ? '收起' : '展开全部'}
          </button>
        )}
      </div>
    </div>
  )
}

// eslint-disable-next-line complexity, max-lines-per-function
export default function TaskDetail({ task, tasks, onClose, onCancel, _onMove, onToggleSubtask, onAdvance, onOpenDocs, onOpenTask, onRetry }) {
  const closeRef = useRef(null)
  const [saveAsTpl, setSaveAsTpl] = useState(null)
  const [saveBusy, setSaveBusy] = useState(false)
  const [saveErr, setSaveErr] = useState(null)
  const [events, setEvents] = useState([])
  const [eventsLoading, setEventsLoading] = useState(false)
  const [depEdit, setDepEdit] = useState(false)
  const [depList, setDepList] = useState([])
  const [depPick, setDepPick] = useState('')
  const [depBusy, setDepBusy] = useState(false)
  const [depErr, setDepErr] = useState(null)
  const [readiness, setReadiness] = useState(null)  // { items, counts, plan, ready, computed_at }
  const [readyTick, setReadyTick] = useState(0)     // 手动/自动刷新计数
  const readyTaskRef = useRef(null)
  const [tab, setTab] = useState('disc')
  // 新建讨论：详情页此前只能「看」讨论、没有创建入口，而阶段门控要求至少一条记录，
  // 面板指引「去新建」却无处可点（用户 2026-11-05 问「这个讨论要怎么进行」）。
  // discList 是本地覆盖层：新建成功后立即生效，换任务时清空回落到 task.discussions。
  const [discList, setDiscList] = useState(null)
  const [discFormOpen, setDiscFormOpen] = useState(false)
  const [discTopic, setDiscTopic] = useState('')
  const [discAgent, setDiscAgent] = useState('用户')
  const [discConcl, setDiscConcl] = useState('')
  const [discBusy, setDiscBusy] = useState(false)
  const [discErr, setDiscErr] = useState(null)

  useEffect(() => {
    closeRef.current?.focus()
  }, [])

  useEffect(() => {
    setDiscList(null)
    setDiscFormOpen(false)
    setDiscErr(null)
  }, [task?.id])

  // Esc 只归栈顶浮层（Phase 2 D1/C-2）：详情开着时若文档面板也在栈顶，Esc 先关文档。
  useOverlayStack(onClose)

  useEffect(() => {
    if (!task?.id) return
    setEventsLoading(true)
    api.getTaskEvents(task.id, 30).then(r => setEvents(r.events || [])).catch(() => setEvents([])).finally(() => setEventsLoading(false))
    // 带上 state：面板内重试/推进后 task 快照会被替换（不关面板），执行历史要跟着重拉，
    // 否则刚发生的 task_retry_manual 事件在列表里看不到。
  }, [task?.id, task?.state])

  // 就绪度：随 state / stage 变化重算——推进、重试、裁决、补文档都会改变结果
  useEffect(() => {
    if (!task?.id) return
    let alive = true
    // 换任务才清空（显示「正在检查」）；同一任务刷新时保留旧结论，避免每 30 秒闪一次
    if (readyTaskRef.current !== task.id) {
      readyTaskRef.current = task.id
      setReadiness(null)
    }
    api.getTaskReadiness(task.id)
      .then(d => { if (alive) setReadiness(d) })
      .catch(() => {
        if (alive) setReadiness({
          items: [], plan: [], ready: true,
          counts: { flow: 0, input: 0, risk: 0, blocking: 0, warning: 0, info: 0 },
        })
      })
    return () => { alive = false }
  }, [task?.id, task?.state, task?.stage, task?.updated_at, readyTick])

  // 结论是后端每次现算的，但只有在拉取时才刷新：详情开着时每 30 秒拉一次，
  // 切回窗口再拉一次——否则别人改了文档/子任务，这个面板会一直停在旧结论上。
  useEffect(() => {
    if (!task?.id) return
    const tick = () => setReadyTick(n => n + 1)
    const timer = setInterval(tick, 30000)
    window.addEventListener('focus', tick)
    return () => { clearInterval(timer); window.removeEventListener('focus', tick) }
  }, [task?.id])

  // 有数据时自动选到最相关的 Tab
  useEffect(() => {
    if (!task?.id) return
    const hasSub = (task.subtasks || []).length > 0
    const hasDisc = (task.discussions || []).length > 0
    const hasDeps = (task.depends_on || []).length > 0
    const hasPart = (task.labels || []).some(l => String(l).startsWith('part-of:'))
    if (hasPart) setTab('workstream')
    else if (hasDisc) setTab('disc')
    else if (hasSub) setTab('subtasks')
    else if (hasDeps) setTab('deps')
    else setTab('activity')
  }, [task?.id])

  // 根任务没有 part-of 标签，但有工作流成员时也默认展示工作流
  useEffect(() => {
    if (!task?.id) return
    let dead = false
    api.getWorkstream(task.id)
      .then(d => { if (!dead && (d.nodes || []).length) setTab('workstream') })
      .catch(() => {})
    return () => { dead = true }
  }, [task?.id])

  const sidx = STAGE_FLOW.indexOf(task.stage)
  const spct = sidx >= 0 ? Math.round((sidx + 1) / STAGE_FLOW.length * 100) : 0
  const comp = completionOf(task)
  const p = prio(task.priority)
  const st = tone(task.state)
  // failed 任务同样可以「取消任务」：后端 T14 对 (failed,*)→cancelled 是放行的，
  // 之前只有 queued/claimed/retrying 显示按钮，导致失败任务在详情里只剩「重试」一条路
  // （用户 2026-11-04 提问「失败的只有重试吗」）。失败任务想彻底结束就该能一键关闭。
  const cancellable = task.state === 'queued' || task.state === 'claimed'
    || task.state === 'retrying' || task.state === 'failed'
  const movable = ACTIVE.includes(task.state)
  const retryable = task.state === 'failed' || task.state === 'retrying'
  const [retryCountdown, setRetryCountdown] = useState(task.retry_countdown ?? null)
  useEffect(() => {
    if (task.state !== 'retrying' || !task.retry_at) {
      setRetryCountdown(null)
      return
    }
    const tick = () => {
      const rt = parseUtc(task.retry_at)
      const diff = Math.max(0, Math.floor((rt - new Date()) / 1000))
      setRetryCountdown(diff)
    }
    tick()
    const id = setInterval(tick, 1000)
    return () => clearInterval(id)
  }, [task.retry_at, task.state])
  const due = task.due_at ? parseUtc(task.due_at) : null
  const overdue = !!due && !Number.isNaN(+due) && due < new Date()
  const hasCtx = task.project || task.workspace || (task.files && task.files.length) || (task.deliverables && task.deliverables.length)
  const discussionsNow = discList ?? task.discussions
  const discGroups = discussionsNow
    ? DISC_GROUPS.map(g => ({ ...g, items: discussionsNow.filter(d => discGroupId(d.stage) === g.id) })).filter(g => g.items.length > 0)
    : []

  const submitDiscussion = async () => {
    if (!discTopic.trim() || discBusy) return
    setDiscBusy(true)
    setDiscErr(null)
    try {
      await api.addDiscussion(task.id, {
        topic: discTopic.trim(),
        agent: discAgent.trim() || '用户',
        stage: task.stage,
        conclusions: discConcl.trim(),
      })
      const r = await api.getTask(task.id)
      setDiscList(r.discussions || [])
      setDiscFormOpen(false)
      setDiscTopic('')
      setDiscConcl('')
    } catch (e) {
      setDiscErr(e.message)
    } finally {
      setDiscBusy(false)
    }
  }
  const discCount = (task.discussions || []).length
  const runCount = (task.runs || []).length
  const docKinds = docKindList(task)
  const docCount = docKinds.length
  const accLines = acceptanceLines(task.acceptance_criteria)
  const stageMeta = task.stage ? STAGE_META[task.stage] : null

  const tabCounts = useMemo(() => ({
    blockers: readiness ? (readiness.counts.blocking || 0) + (readiness.counts.warning || 0) : 0,
    deps: (task.depends_on || []).length,
    subtasks: (task.subtasks || []).length,
    disc: discCount,
    activity: (task.history || []).length + events.length + runCount,
  }), [task, discCount, events.length, runCount, readiness])

  return (
    <div className="overlay drawer-overlay" onClick={onClose}>
      <aside className="drawer" role="dialog" aria-modal="true" aria-label="任务详情" onClick={e => e.stopPropagation()}>
        <header className="drawer__head">
          <div>
            <span className={`state-chip${st === 'live' ? ' is-live' : ''}${st === 'warn' ? ' is-warn' : ''}${st === 'danger' ? ' is-danger' : ''}`}>
              <i />{task.state}
            </span>
            <h2>{task.title}</h2>
          </div>
          <button className="modal__close" ref={closeRef} onClick={onClose} aria-label="关闭">×</button>
        </header>

        {/* 仪表盘条：结论先行，数字大字化 */}
        <div className="td-dash" aria-label="任务概览">
          <div className="td-dash__hero">
            <div
              className="td-dash__ring"
              style={{ '--pct': comp.pct }}
              title={`${comp.source}完成度`}
            >
              <span className="td-dash__pct">{comp.pct}<em>%</em></span>
            </div>
            <div className="td-dash__hero-meta">
              <span className="td-dash__hero-label">完成度</span>
              <span className="td-dash__hero-sub mono">{comp.label}{comp.source !== '—' ? ` · ${comp.source}` : ''}</span>
              {task.stage && (
                <span className={`td-dash__stage chip chip--${stageMeta?.tone || 'dim'}`}>
                  {stageMeta?.label || task.stage}
                </span>
              )}
              {readiness && (
                readiness.ready
                  ? <span className="td-dash__ready" title="流程、输入、风险三层都没有硬阻塞">可开工</span>
                  : (
                    <button
                      type="button"
                      className="td-dash__blocker"
                      onClick={() => setTab('blockers')}
                      title="点击查看要先解哪几项，以及建议顺序"
                    >先解 {readiness.counts.blocking} 项</button>
                  )
              )}
            </div>
          </div>
          <div className="td-dash__metrics">
            <div className="td-dash__metric">
              <span className="td-dash__m-label">优先级</span>
              <span className={`np-row__prio np-row__prio--p${p.p} td-dash__prio`}>{p.label} · {p.text}</span>
            </div>
            <div className="td-dash__metric">
              <span className="td-dash__m-label">讨论</span>
              <b className="td-dash__num">{discCount}</b>
            </div>
            <div className="td-dash__metric">
              <span className="td-dash__m-label">执行</span>
              <b className="td-dash__num">{runCount}</b>
            </div>
            <div className="td-dash__metric">
              <span className="td-dash__m-label">文档</span>
              <b className="td-dash__num">{docCount}</b>
            </div>
            <div className="td-dash__metric">
              <span className="td-dash__m-label">尝试</span>
              <b className="td-dash__num">{task.attempt ?? 0}<em>/{task.max_retries ?? 3}</em></b>
            </div>
          </div>
        </div>

        {task.stage && (
          <div className="stage-bar" title={`${sidx + 1}/${STAGE_FLOW.length} · ${spct}% · ${stageMeta?.label || task.stage}`}>
            <div className="stage-bar__fill" style={{ width: spct + '%' }} />
          </div>
        )}

        <div className="td-quick">
          {(docKinds.length > 0 || task.workspace) && (
            <button className="btn btn--primary" onClick={onOpenDocs}>
              查看文档 · {docKinds.length ? docKinds.join(' / ') : '自动发现'}
            </button>
          )}
          {task.review_result && (
            <span className="td-quick__review" title={task.review_result}>有审查结论</span>
          )}
        </div>

        {/* 核心信息：精简 kv（去掉已上仪表盘的优先级） */}
        <div className="drawer__meta">
          <div className="kv"><span>ID</span><b className="mono">{task.id}</b></div>
          <div className="kv"><span>目标 Agent</span><b>{task.target_agent_type || '任意 agent'}</b></div>
          <div className="kv"><span>预估时长</span><b>{fmtDur(task.est_duration_min)}</b></div>
          <div className="kv"><span>排期</span><b>{scheduleOf(task)}</b></div>
          <div className="kv"><span>创建时间</span><b className="mono">{fmtDate(task.created_at)}</b></div>
          {task.retry_at && task.state === 'retrying' && (
            <div className="kv"><span>下次重试</span><b className="mono">{fmtDate(task.retry_at)} {retryCountdown !== null ? `(${retryCountdown}s 后)` : ''}</b></div>
          )}
          {task.retry_backoff_seconds && task.state === 'retrying' && (
            <div className="kv"><span>退避间隔</span><b className="mono">{task.retry_backoff_seconds}s (2^{task.attempt}×2)</b></div>
          )}
          {due && (
            <div className={`kv${overdue ? ' is-due' : ''}`}>
              <span>截止时间</span>
              <b className="mono">{fmtDate(task.due_at)}{overdue ? ' ⚠' : ''}</b>
            </div>
          )}
        </div>

        {task.review_result && (
          <section className="drawer__sec">
            <h3>审查结论</h3>
            <p className="drawer__desc">{task.review_result}</p>
          </section>
        )}

        {/* 描述卡片 */}
        {task.description && (
          <section className="drawer__sec td-card">
            <h3 className="td-card__title"><span className="td-card__icon" aria-hidden="true">☰</span>描述</h3>
            <p className="drawer__desc td-card__body">{task.description}</p>
          </section>
        )}

        {/* 验收标准：逐行扫读 */}
        {task.acceptance_criteria && (
          <section className="drawer__sec td-card">
            <h3 className="td-card__title"><span className="td-card__icon" aria-hidden="true">✓</span>验收标准</h3>
            {accLines.length > 1 ? (
              <ol className="td-acc">
                {accLines.map((line, idx) => (
                  <li key={idx} className="td-acc__item">{line}</li>
                ))}
              </ol>
            ) : (
              <p className="drawer__desc td-card__body">{task.acceptance_criteria}</p>
            )}
          </section>
        )}

        {task.runs && task.runs.length > 0 && (
          <section className="drawer__sec">
            <h3>完成报告 · {task.runs.length} 次执行</h3>
            // eslint-disable-next-line complexity
            {task.runs.map(r => {
              const ok = r.state === 'FINISHED' && (r.exit_code ?? 0) === 0
              // 窄门禁（d468e633 FR-5/6）：block 级 → 红框拦截卡；
              // warn 级 → 琥珀提示行（文案已由后端保证含「不影响放行」）。
              const anns = r.annotations || []
              const blocked = anns.filter(a => a.level === 'block')
              const warns = anns.filter(a => a.level !== 'block')
              const ds = r.diff_summary
              return (
                <div key={r.id} className={`run-report${ok ? ' is-ok' : r.exit_code ? ' is-fail' : ''}`}>
                  <div className="run-report__head">
                    <b className="mono">{r.agent_name || 'agent'}</b>
                    <span className={`chip${ok ? ' disc-status' : r.exit_code ? ' chip--due' : ''}`}>{r.state}{r.attempt > 1 ? ` · 第 ${r.attempt} 次` : ''}</span>
                    {r.reap_reason && (
                      <span className="chip chip--due"
                            title={`系统回收（${r.reap_reason}）：这条 run 没有提交结果，结果字段是服务端写的`}>
                        系统回收 · 未提交结果
                      </span>
                    )}
                    <span className="hist-row__at mono">
                      {r.started_at ? fmtDate(r.started_at) : ''}{r.finished_at ? ` → ${fmtDate(r.finished_at)}` : ''}
                    </span>
                    {r.rejections > 0 && (
                      <span className="chip chip--due">被拒 {r.rejections} 次</span>
                    )}
                  </div>
                  {blocked.map((a, i) => (
                    <div key={`b${i}`} className="run-report__blocked">
                      <b>已被拦截</b>
                      <span>{a.message}</span>
                    </div>
                  ))}
                  {warns.map((a, i) => (
                    <div key={`w${i}`} className="run-report__warn">
                      <b>提示</b>
                      <span>{a.message}</span>
                    </div>
                  ))}
                  {ds && ds.reason && (
                    <div className="run-report__diff mono">
                      改动证据：{ds.reason}
                      {ds.changed !== undefined ? `（changed=${String(ds.changed)}）` : ''}
                    </div>
                  )}
                  {r.result && <pre className="run-report__body mono">{r.result}</pre>}
                </div>
              )
            })}
          </section>
        )}

        {task.labels && task.labels.length > 0 && (
          <section className="drawer__sec">
            <h3>标签</h3>
            <div className="drawer__labels">
              {task.labels.map(l => (
                <span key={l} className="chip chip--label">{l}</span>
              ))}
            </div>
          </section>
        )}

        {hasCtx && (
          <section className="drawer__sec">
            <h3>上下文</h3>
            {task.project && <div className="kv"><span>项目</span><b>{task.project}</b></div>}
            {task.workspace && <div className="kv"><span>工作区</span><b className="mono">{task.workspace}</b></div>}
            {task.files && task.files.length > 0 && (
              <>
                <div className="ctx-label">关联文件</div>
                <div className="ctx-list">
                  {task.files.map((f, idx) => <div key={idx} className="ctx-file mono">▸ {f}</div>)}
                </div>
              </>
            )}
            {task.deliverables && task.deliverables.length > 0 && (
              <>
                <div className="ctx-label">产出物</div>
                <div className="ctx-list">
                  {task.deliverables.map((f, idx) => <div key={idx} className="ctx-file mono">◆ {f}</div>)}
                </div>
              </>
            )}
          </section>
        )}

        {/* 关系区：Tab 折叠，降低滚动深度 */}
        <section className="drawer__sec td-tabs">
          <div className="td-tabs__bar" role="tablist" aria-label="任务关系">
            {TAB_DEFS.map(t => (
              <button
                key={t.id}
                role="tab"
                aria-selected={tab === t.id}
                className={`td-tabs__tab${tab === t.id ? ' is-active' : ''}`}
                onClick={() => setTab(t.id)}
              >
                {t.label}
                {tabCounts[t.id] > 0 && <span className="td-tabs__count">{tabCounts[t.id]}</span>}
              </button>
            ))}
          </div>

          <div className="td-tabs__panel" role="tabpanel">
            {tab === 'workstream' && (
              <WorkstreamPanel task={task} onOpen={onOpenTask} />
            )}

            {tab === 'blockers' && (
              !readiness ? (
                <p className="detail-muted">正在检查就绪度…</p>
              ) : readiness.items.length === 0 ? (
                <p className="detail-muted">可开工：流程约束、执行输入、执行风险均无未解决项。</p>
              ) : (
                <>
                  <p className="ready-intro">
                    这里列的是这条任务现在开不了工的原因。每条给五段：问题（现象与机制）、依据（可核查的字段与期望值）、
                    影响、处理步骤、责任方；标题右侧的标签是性质分类（门控 / 输入缺口 / 记录缺失 / 外部条件 / 执行顺序）。
                    就绪度本身只是检查结果，不拦任何操作；真正会拦你的是阶段推进（返回 422）和收尾检查。
                  </p>
                  <p className="ready-hint">
                    <span>按序号依次处理；「阻塞」项未解除前，阶段推进会返回 422。</span>
                    <span className="ready-hint__meta">
                      {readiness.computed_at && (
                        <>数据截至 {new Date(readiness.computed_at).toLocaleTimeString('zh-CN', { hour12: false })}</>
                      )}
                      <button type="button" className="ready-hint__refresh"
                        onClick={() => setReadyTick(n => n + 1)}>刷新</button>
                    </span>
                  </p>
                  <section className="ready-table-wrap">
                    <div className="ready-table__cap">
                      <span className="ready-table__title">问题总览</span>
                      <span className="ready-table__hint">先用这张表定位，点行跳到下面的详情；「依据」是可核查的字段与期望值。</span>
                    </div>
                    <table className="ready-table">
                      <thead>
                        <tr><th>#</th><th>问题</th><th>性质</th><th>依据</th><th>责任方</th></tr>
                      </thead>
                      <tbody>
                        {readiness.items.map(b => (
                          <tr key={`ov-${b.order}-${b.kind}`} className={`is-${b.severity}`}
                              onClick={() => document.getElementById(`ready-item-${b.order}`)
                                ?.scrollIntoView({ behavior: 'smooth', block: 'center' })}>
                            <td className="ready-table__n">{b.order}</td>
                            <td className="ready-table__name">
                              {b.severity === 'blocking' && <span className="ready-table__sev">阻塞</span>}
                              {b.title}
                            </td>
                            <td className="ready-table__nature">{b.nature || '—'}</td>
                            <td className="ready-table__ev">{b.evidence || '—'}</td>
                            <td className="ready-table__owner">{b.owner || '—'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </section>
                  {READY_LAYERS.map(layer => {
                    const rows = readiness.items.filter(i => i.layer === layer.id)
                    if (!rows.length) return null
                    return (
                      <section key={layer.id} className="ready-group">
                        <div className="ready-group__head">
                          <span className="ready-group__title">{layer.label}</span>
                          <span className="ready-group__count">{rows.length}</span>
                          <span className="ready-group__hint">{layer.hint}</span>
                        </div>
                        <ul className="blocker-list">
                          // eslint-disable-next-line complexity
                          {rows.map((b, i) => (
                            <li key={`${b.kind}-${i}`} id={`ready-item-${b.order}`} className={`blocker-row is-${b.severity}`}>
                              <div className="blocker-row__head">
                                <span className="blocker-row__order">{b.order}</span>
                                <span className={`chip chip--${b.severity === 'blocking' ? 'danger' : b.severity === 'info' ? 'info' : 'warn'}`}>
                                  {b.severity === 'blocking' ? '阻塞' : b.severity === 'info' ? '排队' : '注意'}
                                </span>
                                {b.nature && <span className="blocker-row__nature">{b.nature}</span>}
                                <span className="blocker-row__title">{b.title}</span>
                              </div>
                              {b.because && (
                                <p className="blocker-row__line is-because">
                                  <span className="blocker-row__tag">问题</span>{b.because}
                                </p>
                              )}
                              {b.evidence && (
                                <p className="blocker-row__line is-evidence">
                                  <span className="blocker-row__tag">依据</span><code>{b.evidence}</code>
                                </p>
                              )}
                              {b.source_ref && b.source_ref.rule && (
                                <p className="blocker-row__line is-rule">
                                  <span className="blocker-row__tag">规则</span>
                                  {b.source_ref.rule}
                                  {b.source_ref.defined_at && <>（定义于 <code>{b.source_ref.defined_at}</code>）</>}
                                  {b.source_ref.doc && <>；出处：{b.source_ref.doc}</>}
                                </p>
                              )}
                              {(b.members || []).length > 1 && (
                                <ul className="blocker-row__members">
                                  // eslint-disable-next-line complexity
                                  {b.members.map((m, mi) => {
                                    if (typeof m === 'string') return <li key={mi}>{m}</li>
                                    return (
                                      <li key={m.code || mi}>
                                        <span className="bm-code">{m.code || '·'}</span>
                                        <span className="bm-name">{m.name}</span>
                                        {m.mins ? <span className="bm-meta">{m.mins}min</span> : null}
                                        {(m.dep_open_txt || (m.dep_open || []).length > 0) && (
                                          <span className="bm-dep">待前置 {m.dep_open_txt || m.dep_open.join('、')}</span>
                                        )}
                                        {m.status === 'blocked' && !(m.dep_open || []).length && (
                                          <span className="bm-dep">受阻</span>
                                        )}
                                        {(m.blocks || []).length > 0 && (
                                          <span className="bm-blocks">阻塞 {m.blocks.join('、')}</span>
                                        )}
                                        {m.note ? <span className="bm-note">{m.note}</span> : null}
                                        {m.desc ? <span className="bm-note">{m.desc}</span> : null}
                                        {(m.blocks_items || []).length > 0 ? (
                                          <span className="bm-blocks-line">
                                            <span className="bm-fix__tag">阻塞条目</span>
                                            {(m.blocks_items).map(bi => (
                                              <span key={bi.code || bi.name} className="bm-block-item">
                                                {bi.code ? <b>{bi.code}</b> : null}
                                                {bi.name ? <span className="bm-bi-name">{bi.name}</span> : null}
                                                {bi.action ? <span className="bm-bi-act">→ {bi.action}</span> : null}
                                              </span>
                                            ))}
                                          </span>
                                        ) : m.blocks_txt ? (
                                          <span className="bm-blocks-line">
                                            <span className="bm-fix__tag">阻塞条目</span>{m.blocks_txt}
                                          </span>
                                        ) : null}
                                        {m.fix_action && (
                                          <span className="bm-fix">
                                            <span className="bm-fix__tag">{m.fix_label || '下一步'}</span>
                                            {(m.fix_steps || []).length === 0 ? <span>{m.fix_action}</span> : null}
                                            {m.fix_owner ? <span className="bm-owner">责任方 {m.fix_owner}</span> : null}
                                          </span>
                                        )}
                                        {(m.fix_steps || []).length > 0 ? (
                                          <ol className="bm-steps">
                                            {m.fix_steps.map((x, xi) => <li key={xi}>{x}</li>)}
                                          </ol>
                                        ) : null}
                                      </li>
                                    )
                                  })}
                                </ul>
                              )}
                              {(b.steps || []).length > 0 ? (
                                <div className="blocker-row__line is-todo">
                                  <span className="blocker-row__tag">处理步骤</span>
                                  <ol className="blocker-row__steps">
                                    {b.steps.map((s, si) => <li key={si}>{s}</li>)}
                                  </ol>
                                  {b.owner ? (
                                    <div className="blocker-row__owner">责任方：{b.owner}</div>
                                  ) : null}
                                </div>
                              ) : b.todo ? (
                                <p className="blocker-row__line is-todo">
                                  <span className="blocker-row__tag">处理方式</span>{b.todo}
                                </p>
                              ) : null}
                              {(b.consequence || b.api) && (
                                <details className="blocker-row__more">
                                  <summary>影响与接口</summary>
                                  {b.consequence && (
                                    <p className="blocker-row__line">
                                      <span className="blocker-row__tag">后果</span>{b.consequence}
                                    </p>
                                  )}
                                  {b.api && <code className="blocker-row__api">{b.api}</code>}
                                </details>
                              )}
                            </li>
                          ))}
                        </ul>
                      </section>
                    )
                  })}
                </>
              )
            )}

            {tab === 'deps' && (
              <>
                {(task.depends_on || []).length === 0 ? (
                  <p className="detail-muted">无前置任务</p>
                ) : (
                  <ul className="dep-list">
                    {task.depends_on.map(did => {
                      const dep = (tasks || []).find(x => x.id === did)
                      return (
                        <li key={did}>
                          <span>{dep ? dep.title : did}</span>
                          <span className="tag">{dep ? (dep.state === 'completed' || dep.stage === 'done' ? '已完成' : dep.state) : '缺失'}</span>
                        </li>
                      )
                    })}
                  </ul>
                )}
                <div className="dep-edit">
                  {!depEdit ? (
                    <button className="btn btn--ghost btn--xs"
                            onClick={() => { setDepList([...(task.depends_on || [])]); setDepPick(''); setDepErr(null); setDepEdit(true) }}>
                      编辑依赖
                    </button>
                  ) : (
                    <div className="dep-edit__box">
                      <ul className="dep-list">
                        {depList.length === 0 && <li className="detail-muted">（无前置）</li>}
                        {depList.map(did => (
                          <li key={did}>
                            <span>{(tasks || []).find(x => x.id === did)?.title || did}</span>
                            <button className="btn btn--ghost btn--xs"
                                    onClick={() => setDepList(l => l.filter(x => x !== did))}>移除</button>
                          </li>
                        ))}
                      </ul>
                      <div className="dep-edit__add">
                        <select className="inp inp--xs" value={depPick} onChange={e => setDepPick(e.target.value)}>
                          <option value="">选择前置任务…</option>
                          {(tasks || [])
                            .filter(x => x.id !== task.id && !depList.includes(x.id))
                            .map(x => <option key={x.id} value={x.id}>{x.title}</option>)}
                        </select>
                        <button className="btn btn--ghost btn--xs" disabled={!depPick}
                                onClick={() => { if (depPick) { setDepList(l => [...l, depPick]); setDepPick('') } }}>
                          添加
                        </button>
                      </div>
                      {depErr && <p className="dep-edit__err">{depErr}</p>}
                      <div className="dep-edit__actions">
                        <button className="btn btn--primary btn--xs" disabled={depBusy}
                                onClick={async () => {
                                  setDepBusy(true); setDepErr(null)
                                  try {
                                    await api.updateTask(task.id, { depends_on: depList })
                                    setDepEdit(false)
                                  } catch (e) {
                                    setDepErr(e?.message || String(e))
                                  } finally { setDepBusy(false) }
                                }}>
                          {depBusy ? '保存中…' : '保存依赖'}
                        </button>
                        <button className="btn btn--ghost btn--xs" onClick={() => setDepEdit(false)}>取消</button>
                      </div>
                      <p className="detail-muted dep-edit__hint">引用自身或构成依赖环会被后端拒绝（422）；保存后列表自动刷新。</p>
                    </div>
                  )}
                </div>
                <div style={{ marginTop: 12 }}>
                  <DependencyGraph task={task} tasks={tasks} onOpen={onOpenTask} />
                </div>
              </>
            )}

            {tab === 'subtasks' && (
              (!task.subtasks || task.subtasks.length === 0) ? (
                <p className="detail-muted">无子任务</p>
              ) : (
                <div className="drawer__subtasks">
                  {task.subtasks.map(st => {
                    const done = st.status === 'done'
                    return (
                      <label key={st.id} className={`subtask-row${done ? ' is-done' : ''}`}>
                        <input
                          type="checkbox"
                          checked={done}
                          onChange={() => onToggleSubtask(st.id, !done)}
                          aria-label={`子任务 ${st.title}`}
                        />
                        <span className="subtask-title">{st.title}</span>
                        <span className="subtask-status">{st.status}</span>
                      </label>
                    )
                  })}
                </div>
              )
            )}

            {tab === 'disc' && (
              <>
              <div className="disc-newbar">
                <button className="btn btn--ghost btn--xs"
                  onClick={() => setDiscFormOpen(o => !o)}>
                  {discFormOpen ? '收起' : '新建讨论'}
                </button>
                <span className="detail-muted">
                  阶段门控只看这条任务上有没有讨论记录；有结论就填 conclusions，保存后即为「已结束」。
                </span>
              </div>
              {discFormOpen && (
                <div className="disc-form">
                  <input
                    className="disc-form__topic"
                    placeholder="topic：这次要做什么、为什么这么做"
                    value={discTopic}
                    onChange={e => setDiscTopic(e.target.value)}
                  />
                  <input
                    className="disc-form__agent"
                    placeholder="发起人（agent 名或「用户」）"
                    value={discAgent}
                    onChange={e => setDiscAgent(e.target.value)}
                  />
                  <textarea
                    className="disc-form__concl"
                    rows={3}
                    placeholder="conclusions：讨论出的结论；留空则保持「进行中」，之后可在讨论里补结论再结束"
                    value={discConcl}
                    onChange={e => setDiscConcl(e.target.value)}
                  />
                  {discErr && <p className="detail-err">保存失败：{discErr}</p>}
                  <div className="disc-form__actions">
                    <button className="btn btn--primary btn--xs"
                      disabled={discBusy || !discTopic.trim()}
                      onClick={submitDiscussion}>
                      {discBusy ? '保存中…' : '保存'}
                    </button>
                  </div>
                </div>
              )}
              {discGroups.length === 0 ? (
                <p className="detail-muted">暂无讨论。点上面的「新建讨论」补一条，阶段推进就能过。</p>
              ) : (
                discGroups.map(g => (
                  <div key={g.id} className="disc-group">
                    <h4 className="disc-group__title">
                      {g.label}
                      <span className="disc-group__count">{g.items.length}</span>
                    </h4>
                    {g.items.map(d => (
                      <div key={d.id} className="disc-block">
                        <div className="disc-block__head">
                          <b className="disc-block__topic">{d.topic}</b>
                          <span className="disc-block__right">
                            <span className="chip disc-stage">{discStageLabel(d.stage)}</span>
                            <span className={`chip disc-status${d.status === 'closed' ? ' is-closed' : ''}`}>
                              {d.status === 'closed' ? '已结束' : '进行中'}
                            </span>
                          </span>
                        </div>
                        {d.agent && <div className="disc-block__agent mono">{d.agent}</div>}
                        {d.summary && <p className="disc-block__summary">{d.summary}</p>}
                        {d.conclusions && (
                          <p className="disc-block__concl"><em>结论:</em> {d.conclusions}</p>
                        )}
                      </div>
                    ))}
                  </div>
                ))
              )}
              </>
            )}

            {tab === 'activity' && (
              <>
                {task.history && task.history.length > 0 && (
                  <>
                    <h4 className="td-subhead">执行历史 · {task.history.length}</h4>
                    <div className="drawer__timeline">
                      {task.history.map(h => <HistRow key={h.id} h={h} />)}
                    </div>
                  </>
                )}
                {events.length > 0 ? (
                  <>
                    <h4 className="td-subhead">状态变更 · {events.length} 条</h4>
                    <div className="event-timeline">
                      {events.map(ev => {
                        const cl = compositeLabel(ev.to_state, ev.to_stage)
                        const actorLabel = ev.actor_type === 'agent' ? ev.actor_id : ev.actor_type === 'user' ? '用户' : '系统'
                        return (
                          <div key={ev.id} className={`event-row event-row--${cl.tone}`}>
                            <span className="event-row__dot" aria-hidden="true" />
                            <div className="event-row__body">
                              <div className="event-row__head">
                                <span className={`chip chip--composite chip--${cl.tone}`}>{cl.label}</span>
                                <span className="event-row__actor mono">{actorLabel}</span>
                                <span className="event-row__at mono">{fmtDate(ev.created_at)}</span>
                              </div>
                              {ev.reason && <div className="event-row__reason">{ev.reason}</div>}
                            </div>
                          </div>
                        )
                      })}
                    </div>
                  </>
                ) : (
                  !eventsLoading && (task.history || []).length === 0 && (
                    <p className="detail-muted">暂无执行历史与状态变更</p>
                  )
                )}
                {!eventsLoading && events.length === 0 && (task.history || []).length > 0 && (
                  <p className="detail-muted">暂无状态变更记录</p>
                )}
              </>
            )}
          </div>
        </section>

        <footer className="drawer__foot">
          {retryable && onRetry && (
            <button
              className="btn btn--primary"
              // 重试后保持面板打开：任务已回队列，用户往往要继续看阶段/改字段（用户 2026-11-04）
              onClick={async () => { try { await onRetry(task.id) } catch { /* error handled by App */ } }}
            >重试</button>
          )}
          {task.state === 'retrying' && retryCountdown !== null && (
            <span className="mono" style={{ fontSize: 12, opacity: .7 }}>{retryCountdown}s 后自动重入队列</span>
          )}
          {task.stage && !['done','cancelled'].includes(task.stage) && onAdvance && (
            task.state === 'failed'
              // 失败任务只有「人审推翻失败判定」这一条阶段出路（后端 T25，仅 review→done）。
              // 其它阶段推进必 422（failed 不在流程里），所以不给按钮，免得点了才报错；
              // 想让失败任务继续干活的动作是重试（上方主按钮）。
              ? task.stage === 'review' && (
                  <button className="btn btn--ghost" onClick={() => onAdvance(task)}>人工验收 →</button>
                )
              : (
                  <button className="btn btn--ghost" onClick={() => onAdvance(task)}>推进阶段 →</button>
                )
          )}
          {/* 这里原有「← 上一状态 / 下一状态 →」两个按钮，点击只改本地 state（无 API），
              属于 Phase 2 C-1 记录的「假成功」：刷新后弹回。后端没有置 state 的接口
              （api/tasks.py 的 PATCH 白名单不含 state），故移除，改为一行说明。 */}
          {movable && (
            <span className="td-state-hint" title="状态由 agent 领取与执行驱动；人工可改的是阶段（阶段推进 / 按阶段拖拽）">
              状态由 agent 领取驱动
            </span>
          )}
          {cancellable && (
            <button
              className="btn btn--ghost btn--danger"
              // 确认成功后才关面板；用户在 ConfirmDialog 里点「取消」/按 Esc 时面板保持打开（R2 C-1）
              onClick={async () => { if (await onCancel(task.id)) onClose() }}
            >取消任务</button>
          )}
          <button className="btn btn--ghost" onClick={() => setSaveAsTpl({ title: `模板：${task.title}`, category: '' })}>另存为模板</button>
        </footer>

        {saveAsTpl && (
          <div className="drawer__savetpl">
            {saveErr && <div className="errorbar" role="alert"><span>▲</span><span>{saveErr}</span><button onClick={() => setSaveErr(null)} aria-label="关闭">×</button></div>}
            <h4>另存为模板</h4>
            <div className="field"><label className="field__label">模板标题 <b>*</b></label><input value={saveAsTpl.title} onChange={e => setSaveAsTpl({ ...saveAsTpl, title: e.target.value })} placeholder="模板标题" /></div>
            <div className="field"><label className="field__label">分类</label><input value={saveAsTpl.category} onChange={e => setSaveAsTpl({ ...saveAsTpl, category: e.target.value })} placeholder="data, backend" /></div>
            <div className="modal__foot">
              <button type="button" className="btn btn--ghost" onClick={() => { setSaveAsTpl(null); setSaveErr(null) }}>取消</button>
              <button type="button" className="btn btn--accent" disabled={saveBusy} onClick={async () => {
                if (!saveAsTpl.title.trim()) return
                setSaveBusy(true); setSaveErr(null)
                try {
                  await api.createTemplateFromTask(task.id, { title: saveAsTpl.title.trim(), category: saveAsTpl.category.trim() })
                  setSaveAsTpl(null)
                } catch (e) { setSaveErr(e.message) }
                setSaveBusy(false)
              }}>{saveBusy ? '保存中…' : '保存模板'}</button>
            </div>
          </div>
        )}
      </aside>
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { api } from '../api'
import { confirm } from '../confirm'
import { fmtAgo } from '../constants'

function _emptyForm() {
  return { title: '', description: '', category: '', priority: 0, est_duration_min: 30, target_agent_type: '', acceptance_criteria: '', labels: '', tags: '' }
}

function TemplateForm({ initial, submitLabel, busy, onSubmit, onCancel }) {
  // eslint-disable-next-line complexity
  const [form, setForm] = useState(() => ({
    title: initial?.title || '',
    description: initial?.description || '',
    category: initial?.category || '',
    priority: initial?.priority || 0,
    est_duration_min: initial?.est_duration_min || 30,
    target_agent_type: initial?.target_agent_type || '',
    acceptance_criteria: initial?.acceptance_criteria || '',
    labels: (initial?.labels || []).join(', '),
    tags: (initial?.tags || []).join(', '),
  }))
  const submit = async (e) => {
    e.preventDefault()
    if (!form.title.trim()) return
    const payload = {
      title: form.title.trim(),
      description: form.description.trim(),
      category: form.category.trim(),
      priority: form.priority,
      est_duration_min: form.est_duration_min,
      target_agent_type: form.target_agent_type.trim() || undefined,
      acceptance_criteria: form.acceptance_criteria.trim(),
      labels: form.labels ? form.labels.split(',').map(s => s.trim()).filter(Boolean) : [],
      tags: form.tags ? form.tags.split(',').map(s => s.trim()).filter(Boolean) : [],
    }
    await onSubmit(payload)
  }
  return (
    <form onSubmit={submit}>
      <div className="field"><label className="field__label">模板标题 <b>*</b></label><input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="例如：数据清洗脚本" /></div>
      <div className="field"><label className="field__label">描述</label><textarea value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} rows={2} placeholder="模板说明…" /></div>
      <div className="field field--row">
        <div><label className="field__label">分类</label><input value={form.category} onChange={e => setForm({ ...form, category: e.target.value })} placeholder="data, backend, frontend" /></div>
        <div><label className="field__label">预估时长（分）</label><input type="number" min={5} step={5} value={form.est_duration_min} onChange={e => setForm({ ...form, est_duration_min: +e.target.value })} /></div>
      </div>
      <div className="field"><label className="field__label">目标 Agent</label><input value={form.target_agent_type} onChange={e => setForm({ ...form, target_agent_type: e.target.value })} placeholder="留空=任意" /></div>
      <div className="field"><label className="field__label">验收标准</label><textarea value={form.acceptance_criteria} onChange={e => setForm({ ...form, acceptance_criteria: e.target.value })} rows={2} placeholder="完成定义…" /></div>
      <div className="field field--row">
        <div><label className="field__label">标签</label><input value={form.labels} onChange={e => setForm({ ...form, labels: e.target.value })} placeholder="bug,urgent" /></div>
        <div><label className="field__label">Tags</label><input value={form.tags} onChange={e => setForm({ ...form, tags: e.target.value })} placeholder="tag1,tag2" /></div>
      </div>
      <div className="modal__foot">
        <button type="button" className="btn btn--ghost" onClick={onCancel}>取消</button>
        <button type="submit" className="btn btn--accent" disabled={busy}>{busy ? '处理中…' : submitLabel}</button>
      </div>
    </form>
  )
}

export default function TemplatesView() {
